window.harnessChunks["rows-3b7b6a5baacf5ce2.js"]=["<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-09-16T23:24:44+03:00\"><th scope=\"row\"><a href=\"https://github.com/microsoft/autogen\" target=\"_blank\" rel=\"noopener\">Microsoft AutoGen AgentChat</a><small>2023</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/microsoft/autogen/tree/027ecf0a379bcc1d09956d46d12d44a3ad9cee14\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 027ecf0a379bcc1d09956d46d12d44a3ad9cee14\">027ecf0 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: stateful agents choose tools/actions and incorporate returned results.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: team selection plus Magentic-One&#39;s explicit loop/stall detection and controlled transfer of the next action right suppress uncontrolled repetition/interference among multiple S1 participants. This is more than mere delegation.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: MagenticOneOrchestrator owns a whole-team current facts/plan/progress ledger and has authority to assess progress, choose commitments, reset participants and regenerate the plan when the team stalls. Code-execution approval constrains an operational executor action rather than independently owning this whole-team current-control loop, so no separate (P) mode is published.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: the progress ledger is part of the same operational S3 regulator that directs the team. It is not a distinct complementary audit channel with separate reviewing independence.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: replanning after current-task stalls is inside-now adaptation. No distinct external/prospective intelligence function shaping future organizational posture is established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: participant set, instructions, termination rules and ultimate authority remain application/parent-owned.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/9ee1ea7472777767928c8b2ab035e0948a0467e9/assessments/autogen-agentchat.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 9ee1ea7472777767928c8b2ab035e0948a0467e9\">9ee1ea7 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-09-20T21:45:19+03:00\"><th scope=\"row\"><a href=\"https://github.com/Technion-Kishony-lab/data-to-paper\" target=\"_blank\" rel=\"noopener\">data-to-paper</a><small>2023</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-20\">2026-09-20</time></td><td class=\"review-ref\"><a href=\"https://github.com/Technion-Kishony-lab/data-to-paper/tree/81df14c4b9600466e645c3b2b336cc54daa3df3a\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 81df14c4b9600466e645c3b2b336cc54daa3df3a\">81df14c &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: autonomously perform the environment-facing scientific work needed to transform project data and research state into executable analyses and research artifacts. - Disturbance / variety regulated: heterogeneous datasets, generated-code errors, unexpected outputs/files, statistical-analysis requirements, intermediate product state and manuscript construction requirements. - Decisive decision or feedback right: choose and revise analysis/code/content actions in response to current project products, execution results and validation/reviewer feedback. - Decision owner: the active first-party performer/code-writing agents in the hypothesis-testing workflow. - Supporting / enforcement mechanisms: stage runner, CodeRunner, debugger conversers, code extract/check logic, output requirements, product store, data chaining and configured iteration bounds. - Closure path: current scientific products/data -&gt; agent proposes code/content action -&gt; first-party runner executes/materializes it -&gt; output/error/product state returns -&gt; agent revises or advances. - Boundary reachability: these paths are the shipped hypothesis-testing research workflow invoked by the installable application/CLI, not benchmark-only examples. - Why this is / is not agent-owned: runtime and guardrails execute/check code, but the context-sensitive analysis/content choice and revision remain model-agent decisions. - Evidence: README.md, stepsrunner.py, requestcode.py. - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material first-party S2 coordination path is established at the reviewed recursion. - Disturbance / variety regulated: the workflow contains multiple performer/reviewer roles and research stages, but no concrete interference, conflict or oscillation among distinct S1 units is identified and attenuated by a dedicated coordination relation. - Decisive decision or feedback right: none established for S2. - Decision owner: none established for S2. - Supporting / enforcement mechanisms: typed stage transitions, product passing, paired conversations, deterministic sequencing and rewind/retry utilities. - Closure path: these mechanisms sequence work and transmit review feedback; they do not close a cross-S1 interference-regulation loop. - Why this is / is not agent-owned: interacting agents and state transfer are real, but the reviewed paths are production/review dependencies rather than S2-specific conflict attenuation. - Evidence: stepsrunner.py, dualconverser.py. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no autonomous whole-system inside-and-now control function is established at the reviewed recursion. - Disturbance / variety regulated: stage completion, retries, rewinds, project parameters and review rounds constrain current work, but no first-party autonomous actor is shown holding a whole-project current view plus broad authority over shared resources/commitments/priorities. - Decisive decision or feedback right: stage flow and retry bounds are primarily encoded in deterministic runner logic and project parameters; local reviewers control product acceptance rather than organization-wide current control. - Decision owner: none established for S3. - Supporting / enforcement mechanisms: DataStepRunner/HypothesisTestingStepsRunner, stage enums, product readiness, retry/rewind helpers, project parameters and UI actions. - Closure path: configured stage/retry conditions alter control flow mechanically; no discretionary whole-system S3 owner is evidenced. - Why this is / is not agent-owned: model agents make local scientific/product decisions, while the broader workflow sequence is framework-defined. - Evidence: stepsrunner.py, README.md. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: provide a separate challenge channel that reviews scientific/code/writing products and returns concrete corrective feedback before those products are accepted. - Disturbance / variety regulated: plausible-but-wrong analysis outputs, code/result problems, weak hypotheses/plans, writing defects and other product claims that ordinary performer generation may miss. - Decisive decision or feedback right: independently approve a product or issue constructive concerns that force another performer revision cycle. - Decision owner: the separate reviewer LLM conversation in ReviewDialogDualConverserGPT and review-specific subclasses; in code paths, review agents inspect executed outputs/code products separately from the generating/debugging conversation. - Supporting / enforcement mechanisms: separate ConversationManager, review termination phrase, max review rounds, product extraction/checks, code-review prompts and rewind utilities. - Closure path: performer produces valid candidate -&gt; reviewer receives the candidate/background -&gt; reviewer approves or supplies concerns -&gt; concerns are appended to the performer conversation with explicit correction request -&gt; performer rewrites/revises -&gt; review repeats. - Boundary reachability: the review dialog base class is reused by goal, planning and manuscript-writing review steps in the shipped hypothesis-testing workflow; code review is also embedded in the standard code-product path. - Why this is / is not agent-owned: the reviewer is a separate agent conversation and owns the semantic approve/challenge judgment; deterministic loop code only routes/enforces that judgment. - Claim being audited: that a current scientific product/code result is adequate/correct enough to become accepted workflow state. - Ordinary reporting path: performer response plus normal generated/executed product state. - Complementary access path: separate reviewer conversation receives the product and relevant background/output context; code review can inspect created output contents. - Independence boundary: reviewer has its own conversation manager/role and does not share the performer&#39;s assistant role; review feedback is generated independently and then returned. - Who acts on findings: the original performer/code-writing agent revises the product in the next cycle. - Evidence: dualconverser.py, requestcode.py, stepsrunner.py. - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S4 / adaptation: - State: A(P) - Function: use external literature/novelty evidence to develop or revise future research direction and return the selected direction into the current experimental plan, with both autonomous and Copilot parent-governed modes. - Disturbance / variety regulated: existing literature may make a candidate goal non-novel, external findings may change relevant hypotheses, and a human scientist may judge the proposed future direction inadequate. - Decisive decision or feedback right: in Autopilot, research/novelty agents judge literature-derived novelty and generate/refine the goal/hypothesis; in Copilot, human review can replace/supplement reviewer feedback and require revised research products. - Decision owner: autonomous research/reviewer agents in base mode; human scientist in the supported Copilot parent mode for the reviewed future-direction decision. - Supporting / enforcement mechanisms: literature-search agents, NoveltyAssessmentReview, ReGoalReviewGPT, stage return to GOAL, human-review application interactions, product storage and plan handoff. - Closure path: external literature -&gt; novelty/goal review -&gt; autonomous or parent judgment -&gt; if inadequate, workflow returns to goal generation/refinement -&gt; resulting goal/hypothesis/testing plan feeds data analysis and later research stages. - Boundary reachability: literature/novelty/goal refinement is part of the shipped hypothesis-testing runner, and README plus HumanReviewType/review interaction code expose Copilot human feedback through the same first-party workflow. - Why this is / is not agent-owned: the base mode closes without human direction through model-agent novelty/refinement decisions; the separately supported Copilot mode intentionally transfers the relevant review/judgment right to the human and returns that decision into workflow state. - External distinction: retrieved scientific literature and most-similar-paper evidence. - Future / prospective distinction: whether the current research goal/hypothesis is novel/appropriate enough to warrant future experimentation. - Adaptation option generated: revised research goal/hypothesis and downstream hypothesis-testing plan. - Path back into current capability / S3: failed novelty sets regoal and returns to ScientificStage.GOAL; accepted/revised goal then feeds planning, code analysis and manuscript stages. - Evidence: stepsrunner.py, dualconverser.py, README.md. - Basis: structural -\">A(P)</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no first-party identity/ultimate-policy closure is established. - Disturbance / variety regulated: project parameters, research goals, human feedback and methodological guardrails constrain work, but no identity-level dispute is routed to an ultimate authority and returned as governing organizational policy. - Decisive decision or feedback right: none established for S5. - Decision owner: none established for S5. - Supporting / enforcement mechanisms: startup/project parameters, user research goal, coding guardrails, reviewer prompts and human-review UI. - Closure path: these controls constrain local research behavior directly; no identity/ultimate-policy issue -&gt; authoritative decision -&gt; returned policy loop is evidenced. - Why this is / is not agent-owned: neither autonomous agents nor the Copilot human are shown resolving an identity-level policy issue at this recursion. - Evidence: README.md, stepsrunner.py. - Basis: structural -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/c9da28372ac35ff5d8bc9a74679a6987a5d451df/assessments/data-to-paper.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit c9da28372ac35ff5d8bc9a74679a6987a5d451df\">c9da283 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"1\" data-assessment-at=\"2026-09-21T19:11:00+03:00\"><th scope=\"row\"><a href=\"https://github.com/zhayujie/CowAgent\" target=\"_blank\" rel=\"noopener\">CowAgent</a><small>2022</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-20\">2026-09-20</time></td><td class=\"review-ref\"><a href=\"https://github.com/zhayujie/CowAgent/tree/7c55a61e1bccb82c99d97a4a436f598c079f7c9d\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 7c55a61e1bccb82c99d97a4a436f598c079f7c9d\">7c55a61 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: autonomously transform user/scheduled/delegated objectives into environment-facing tool/skill work and returned outcomes. - Disturbance / variety regulated: heterogeneous user objectives, model uncertainty, tool results/errors, files/shell/browser/service state, channel messages, and follow-up observations encountered during a trajectory. - Decisive decision or feedback right: choose the next reasoning/tool/skill action, incorporate returned observations, delegate bounded work when useful, or stop with a final response. - Decision owner: the running CowAgent Agent/model actor inside the first-party AgentStreamExecutor loop. - Supporting / enforcement mechanisms: ChatService, AgentBridge, provider adapters, prompt/workspace construction, tool registry, permissions, session persistence, scheduler integration and context controls. - Closure path: each tool result, delegated result or new model observation returns into the first-party executor context and can change the next autonomous action until completion. - Boundary reachability: the credited executor/bridge/tool path is the normal shipped Web/channel runtime and is instantiated directly by standard CowAgent operation at the pinned revision. - Why this is / is not agent-owned: deterministic code supplies transport, limits and execution, while the model actor owns the discretionary next-action choice on each loop iteration. - Evidence: pinned agent/chat/service.py and bridge/agentbridge.py; README.md corroborates the shipped planning/tool execution boundary. - Basis: structural and explicit. - Confidence: high. - Caveats: model/provider/tool availability, permissions and iteration limits constrain the Agent&#39;s operational discretion but do not replace its next-action judgment.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: attenuate a concrete interference between sibling operational Agents when concurrent delegations target the same persistent relay conversation. - Disturbance / variety regulated: concurrent handoffs to one source→target relay session would otherwise interleave turns in the target Agent&#39;s transcript and corrupt the shared conversational state used by later delegated work. - Decisive decision or feedback right: serialize admission to that target relay session so exactly one delegated turn occupies it at a time; timeout rather than permit an overlapping handoff when the lock cannot be acquired within policy. - Decision owner: constructor-owned at the assessed boundary. The first-party S2-specific serialization primitive is complete and operational, but the conflict policy itself is deterministic/developer-selected rather than autonomously chosen by an Agent. - Supporting / enforcement mechanisms: per-relay relaylock, stable relay-session derivation, delegation roster/ACL, depth/cycle checks, timeout and synchronous result return. - Closure path: a source Agent&#39;s delegation blocks on the relay lock; after the prior target turn finishes and releases the lock, the next delegated target run executes against a non-interleaved transcript and its result returns to the waiting source Agent, changing that source&#39;s subsequent S1 behavior. - Boundary reachability: agentdelegate is a shipped team tool attached to normal team turns through AgentBridge; no downstream coordinator or test-only actor is required for the serialization path. - Why this is / is not agent-owned: Agents autonomously decide to delegate and select the teammate/task, but once two handoffs conflict the coordination choice is a fixed first-party lock policy. CowAgent therefore exposes a real S2-specific construction path without an autonomous owner of the conflict-regulation decision. - Evidence: pinned agent/tools/agentdelegate/agentdelegate.py and team-session support in bridge/agentbridge.py. - Basis: structural. - Confidence: high. - Caveats: other team features such as speaker selection, shared transcripts and ordinary handoff are not separately credited as S2 merely because they connect Agents. - Distinct S1 units: independently configured live CowAgent Agents with separate profiles/workspaces and first-party execution loops participating in one team conversation. - Inter-S1 disturbance: overlapping delegated turns to the same target relay session can interleave in the target transcript. - Attenuating coordination relation: the first-party per-relay lock queues competing handoffs and allows only one target turn at a time. - Feedback into subsequent S1 behaviour: the coordinated target result is returned synchronously to the delegating source Agent&#39;s tool loop; timeout/failure likewise returns a result that changes the source Agent&#39;s next decision. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the lock exists specifically because concurrent sibling handoffs would interfere by interleaving one operational transcript, and it changes admission/timing to suppress that identified disturbance before results feed back to the source Agent.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S3 / regulation: - State: P - Function: regulate the currently configured CowAgent installation as a whole by changing which operational Agents are available, which models/capabilities they use, and which live channel instances/teams route work to them. - Disturbance / variety regulated: current mismatch between installed operational capacity and the operator&#39;s desired roster, agent availability, model/capability allocation, shared/own knowledge mode, default ownership and live channel/team bindings. - Decisive decision or feedback right: create/update/archive/delete an Agent, make an Agent default, enable/disable it, alter its model/skills/knowledge allocation, or rebind a running channel/team to a different Agent roster. - Decision owner: the authenticated self-hosted operator is the legitimate parent actor in this supported mode. - Supporting / enforcement mechanisms: AgentAdminService, roster revision checks, Web authentication, registry/router rebuilding, scheduler reconciliation, targeted live-runtime eviction and hot channel rebinding. - Closure path: the operator submits a first-party Web/API decision; CowAgent persists it, updates the live registry/router or channel binding, starts/stops the affected schedulers and evicts changed Agent instances so subsequent current work is executed under the returned control decision. - Boundary reachability: the authenticated Web console and its /api/agents administration paths are a standard shipped self-hosted operating surface documented as the unified configuration hub, not a development-only control plane. - Why this is / is not agent-owned: no standard first-party autonomous Agent is given installation-wide roster/model/capability/channel authority. The decisive current-control choice comes from the authenticated operator; runtime code only validates, persists and enforces it. - Evidence: pinned agent/admin.py, channel/web/api/agents.py, and bridge/agentbridge.py scheduler/runtime reconciliation. - Basis: explicit and structural. - Confidence: medium-high. - Caveats: this claim is limited to installation-level current capability/resource control. Per-task steering/cancel and permission enforcement alone would not establish S3, and the assessment does not treat every settings edit as an S3 decision. - Whole-system current view: AgentAdminService.snapshot() exposes the installation&#39;s full current Agent roster, default Agent and channel instances; the same authenticated surface operates over that roster rather than one worker-local state. - Current-control decision scope: availability of S1 units, current model/capability allocation, default Agent, channel/team routing and scheduler participation for the running installation.\">P</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no material first-party complementary and sufficiently independent audit function was established at the declared installation boundary. - Disturbance / variety regulated: none established as an S3 witness; ordinary tool feedback, run/event recording and Self-Evolution review do not provide a materially independent route to operational reality for checking production claims. - Decisive decision or feedback right: no S3-specific independent audit judgment/feedback right is supplied. - Decision owner: not established. - Supporting / enforcement mechanisms: execution/tool events, conversation/run persistence, evolution records/backups, logs and operator inspection surfaces. - Closure path: no independent audit finding→corrective-current-control loop was established; recorded events and evolution changes serve their primary execution/adaptation purposes. - Why this is / is not agent-owned: there is no qualifying audit function whose decisive judgment could be assigned to an autonomous Agent. - Evidence: pinned chat/executor event path, conversation storage, Web/admin surfaces, and agent/evolution/ review path. - Basis: structural. - Confidence: high. - Caveats: a downstream deployment could add an independent verifier or external monitor, but that composed system would be outside this frozen first-party boundary.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:4\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S4 / adaptation: - State: A - Function: convert externally observed conversation patterns and capability failures into prospective adaptations of reusable future capability. - Disturbance / variety regulated: changing user preferences and recurring work patterns, skill defects discovered in real use, reusable workflows not yet encoded as capabilities, and unfinished work whose recurrence or omission would reduce future fit. - Decisive decision or feedback right: after an idle conversation, decide autonomously whether there is a clear durable signal and whether to patch an existing skill, create a new reusable skill, consolidate knowledge/memory, or take no adaptation action. - Decision owner: the isolated first-party Self-Evolution review Agent/model actor. - Supporting / enforcement mechanisms: idle trigger thresholds, restricted evolution toolset, guarded workspace paths, pre-change backup, snapshot diff/change detection, transactional rollback and evolution records. - Closure path: the review Agent senses conversation-derived external signals, selects and writes an adaptation, the executor commits only real guarded changes, and later normal Agent runs load/use the revised skill/knowledge/persona state; if no clear signal exists it explicitly leaves capability unchanged. - Boundary reachability: Self-Evolution is started by normal AgentBridge initialization, its configuration class defaults enabled, and the standard pinned config-template.json ships selfevolutionenabled: true; the decision actor is therefore reachable in the supported distribution without borrowing a dogfood or contributor agent. - Why this is / is not agent-owned: trigger timing, backups and write guards are deterministic support, but the model review Agent owns the discretionary judgment of whether a past external interaction predicts future reusable need and which permitted adaptation to make. - Evidence: pinned agent/evolution/config.py, trigger.py, executor.py, prompts.py, bridge/agentbridge.py, config-template.json and docs/memory/self-evolution.mdx. - Basis: explicit and structural. - Confidence: high. - Caveats: simple memory consolidation alone is not the credited S4 witness. The positive mapping relies on the separately evidenced prospective skill-adaptation path: detecting a workflow likely to be wanted again or a skill defect exposed in use, autonomously generating an adaptation, and returning that change into later capability. - External distinction: the review consumes user conversation and actual skill/task experience from the environment, including repeated preferences, failures and emergent workflows. - Future / prospective distinction: the evolution prompt explicitly asks whether a workflow is reusable and likely to be wanted again, and documentation defines the goal as creating/fixing skills so they can be reused next time and future conversations improve. - Adaptation option generated: patch a defective skill, encode an emergent workflow as a new reusable skill, consolidate durable knowledge/memory, complete suitable unfinished work, or deliberately make no change. - Path back into current capability / S3: committed workspace/skill/knowledge changes are the same first-party artifacts read by subsequent normal Agent operation; operator rollback remains a separate parent intervention path rather than the owner of the autonomous adaptation judgment.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S5 / identity: - State: A(P) - Function: govern the Agent&#39;s durable identity/personality and highest-level workspace behavioral principles through first-party identity files that are loaded into subsequent system prompts. - Disturbance / variety regulated: drift between the Agent&#39;s durable identity/behavioral principles and explicit repeated signals about what the assistant should be, plus explicit operator decisions to redefine those identity/policy artifacts. - Decisive decision or feedback right: in the autonomous mode, decide whether an explicit repeated identity/personality/style signal is strong enough to justify a bounded AGENT.md identity revision; in the parent mode, authoritatively edit AGENT.md/RULE.md through the authenticated core-file administration surface. - Decision owner: base mode — the isolated Self-Evolution review Agent for the deliberately narrow autonomous identity-evolution decision; parent mode — the authenticated self-hosted operator as ultimate authority over the installation&#39;s core identity/policy files. - Supporting / enforcement mechanisms: evolution signal criteria and guarded writes/backups; AgentAdminService core-file revision checks and atomic writes; authenticated Web endpoint; prompt/workspace loader; targeted runtime eviction after operator edits. - Closure path: autonomous mode: repeated identity-level external signal → review-Agent identity judgment → guarded AGENT.md edit → subsequent runtime loads the changed persona. Parent mode: authenticated operator reads/edits a core identity/policy file → atomic persistence and cached-Agent eviction → subsequent Agent instance reloads that file into its system prompt. - Boundary reachability: both modes are shipped supported runtime paths: default-enabled Self-Evolution may edit AGENT.md under its standard guard, while the authenticated Web Agents API exposes core-file read/write and immediately evicts the changed runtime. - Why this is / is not agent-owned: the base identity change is not a static prompt or automatic parser; the review Agent must judge whether a rare explicit repeated signal warrants changing its own identity artifact. The separate operator mode retains parent authority to set or override the same identity/policy surface, hence A(P) rather than plain A. - Evidence: pinned agent/evolution/prompts.py, executor.py, agent/prompt/workspace.py, agent/prompt/builder.py, agent/admin.py and channel/web/api/agents.py. - Basis: explicit and structural. - Confidence: medium-high. - Caveats: ordinary permission settings, tool approvals, memory/preferences and per-task steering are not credited as S5. The autonomous claim is narrowly limited to the explicit first-party AGENT.md identity-evolution path; operator edits establish the separate parent mode. - Identity / ultimate-policy issue: AGENT.md is explicitly defined by the shipped templates as the Agent&#39;s identity/personality and is loaded with RULE.md into the system-prompt context; this is materially different from ordinary task or tool policy. - Ultimate authority in each claimed mode: base (A) — Self-Evolution Agent decides whether the standard rare-signal criterion warrants a durable identity edit; parent (P) — authenticated operator directly owns the authoritative core-file edit and may override/undo Agent evolution. - Return-to-operation path: both modes persist the core file used by prompt construction; operator writes additionally evict the cached runtime, and later Agent initialization reloads the changed identity/policy context.\">A(P)</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/a00011ae5e8e9ee62aa713d51f283559f12102d4/assessments/cowagent.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit a00011ae5e8e9ee62aa713d51f283559f12102d4\">a00011a &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-09-16T23:24:44+03:00\"><th scope=\"row\"><a href=\"https://github.com/agno-agi/agno\" target=\"_blank\" rel=\"noopener\">Agno</a><small>2022</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/agno-agi/agno/tree/44219f8532e2fe6ce936850455f4b9a2567e4194\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 44219f8532e2fe6ce936850455f4b9a2567e4194\">44219f8 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: member agents autonomously execute bounded model/tool work and return results.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: TeamMode.tasks provides an out-of-box agent-owned mutual-adjustment loop over a shared task board. The leader assigns ownership, prevents duplicate tasks, encodes dependencies, observes member outcomes and can retry/reassign/change the plan; dependency state prevents conflicting/premature execution. This goes beyond one-shot delegation.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: the same leader has a current whole-team view of tasks, assignees, dependency/blocked state, results and failures, plus authority to create/reprioritize through dependencies, assign/reassign members, execute work, update status and decide overall completion. That is a concrete agent-owned current-control loop over shared operational commitments. Human-in-the-loop paths pause member/tool execution and return the result to the team; they do not independently take ownership of the team-level assignment/plan/completion right, so no separate (P) mode is published.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: Agno lets applications compose reviewer/critic members, but the standard team runtime does not supply a distinct sufficiently independent audit channel with alternative operational access and required corrective closure.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: memory, knowledge, reasoning and learning capabilities can improve team operation but do not by themselves instantiate a distinct external-and-prospective intelligence function coupled against S3.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: team role, instructions, permissions, approvals and identity are application/parent configured. The tasks leader regulates execution but is not given ultimate agent-owned policy/identity authority or an S3–S4 closure role.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/9ee1ea7472777767928c8b2ab035e0948a0467e9/assessments/agno.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 9ee1ea7472777767928c8b2ab035e0948a0467e9\">9ee1ea7 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"2\" data-assessment-at=\"2026-11-27T16:57:10+03:00\"><th scope=\"row\"><a href=\"https://github.com/signalridge/mare\" target=\"_blank\" rel=\"noopener\">mare</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>2</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-27\">2026-11-27</time></td><td class=\"review-ref\"><a href=\"https://github.com/signalridge/mare/tree/d126cc1f508f44e05e5e6f7e27d4f019d84dd2d9\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision d126cc1f508f44e05e5e6f7e27d4f019d84dd2d9\">d126cc1 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Perform bounded coding tasks. - Disturbance / variety regulated: Partial repository knowledge, tool failures and need for follow-up. - Decisive decision or feedback right: Determine the next task action and interpret outcomes. - Decision owner: The model driving mare&#39;s installed agent preset. - Supporting / enforcement mechanisms: Lua request and dispatch with Rust host confinement and scoped workspace grants. - Closure path: Model calls dispatch against current tool definitions and outcomes return before another model step or final closure. - Boundary reachability: The normal executable loads a first-party loop and supported default workspace action mode. - Why this is / is not agent-owned: The agent selects task operations. Lua and Rust transport and enforce the allowed choices. - Evidence: installed distribution, packaged request and dispatch loop, workspace preset - Basis: Pinned implementation and distribution. - Confidence: High. - Caveats: External model performance was not measured.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: Coordinate branches of the same agent tree competing for bounded descendant execution. - Disturbance / variety regulated: Independent child sessions can request concurrent descendants, exhausting the single root-wide active allowance. - Decisive decision or feedback right: Define a shared reservation, rejection and reclamation relation. - Decision owner: First-party constructor supplies fixed quota and tree-scoped reservation rules. - Supporting / enforcement mechanisms: Atomic host reservation shared across branches, typed limit failures and release notifications. - Closure path: An excess request returns an error to the calling agent instead of starting a competing child. Completion drops the reservation and frees the shared slot. - Boundary reachability: Every supported child request goes through the installed registry bound to the root budget. - Why this is / is not agent-owned: The rules supply explicit interference attenuation. Allocation policy is not revised by independent agents. - Evidence: root-shared reservation, reservation release, shipped subagent actions, capacity error mapping - Basis: Pinned independent-child and admission evidence. - Confidence: High. - Caveats: No claim of general file-level isolation among same-directory children. - Distinct S1 units: Concurrent child sessions with own tasks and contexts, capable of proposing descendant work. - Inter-S1 disturbance: Several branches may simultaneously try to consume the same root-wide child slots. - Attenuating coordination relation: Shared atomic reservation, refusal at capacity and slot release on termination. - Feedback into subsequent S1 behaviour: A rejected spawn returns a tool error to the caller. Later admitted work can consume freed capacity. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: The root-shared limit changes execution outcomes for simultaneous competing child commitments.\">C</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A - Function: Intervene in the current commitments of a root-managed agent team. - Disturbance / variety regulated: Children can be stuck, misdirected, interrupted or no longer worth their current allocation. - Decisive decision or feedback right: Choose whether to steer a specific child or cancel a subtree and redirect the remaining work. - Decision owner: The root model in the supported child execution mode. - Supporting / enforcement mechanisms: Root-scoped listing, completion notices, targeted steering and hierarchical cancellation. - Closure path: The root sees current child commitments and receives outputs. Its instruction enters a running child or cancellation stops that scope and updates the subsequent state. - Boundary reachability: First-party subagent tools are registered for the executing model and apply against the actual scoped host registry. - Why this is / is not agent-owned: The root chooses the corrective action. The operator&#39;s asset views and per-action approvals serve different purposes. - Evidence: list, steer and cancel tools, cancellation scope, child return, operator agent list controls, shipped subagent actions - Basis: Pinned deployed tool, state and effect path. - Confidence: High within the root scope. - Caveats: The Peers tab does not establish a distinct system-wide parent-control mode. - Whole-system current view: Statuses, identities and tasks of the root&#39;s child commitments, plus completion or interruption feedback. - Current-control decision scope: Alter a running child&#39;s work or cancel its subtree and reassign capacity.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3* / direct audit: - State: C - Function: Inspect claims about code changes through a dedicated complementary read-only model review. - Disturbance / variety regulated: A producing session&#39;s own report can miss a concrete defect or an unmet requirement. - Decisive decision or feedback right: Evaluate actual worktree/commit evidence and compose a controller response from findings. - Decision owner: A separate shipped reviewer makes the audit judgment. Acting on the finding requires operator or plugin composition. - Supporting / enforcement mechanisms: Revision/working-tree diff resolver, read-only child session, transcript output and typed completion event. - Closure path: The reviewer returns findings through a function-specific event and UI. No shipped subscriber automatically transforms those findings into root corrective control. - Boundary reachability: The installed review command resolves actual Git evidence, starts a read-only reviewer and emits the supported return event. - Why this is / is not agent-owned: The independent judgment is real. The default root context excludes review findings, so autonomous control closure is not credited. - Evidence: independent Git target resolution, separate reviewer and return, review completion contract, review mode - Basis: Pinned alternative evidence acquisition and dedicated feedback interface. - Confidence: Moderate. - Caveats: The optional approval reviewer decides about proposed actions and is not the audit witness. - Claim being audited: The proposed code change meets its intended requirements without concrete regressions. - Ordinary reporting path: The producing session&#39;s progress/results or local test output. - Complementary access path: Separate target resolution over staged, unstaged, untracked, base or commit evidence and review-specific read tools. - Independence boundary: A fresh read-only, role-specific model session acquires Git evidence; its output stays out of the producing model&#39;s default context. - Who acts on findings: An operator can use the transcript or a constructor can connect the typed review return to a controller response.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S4 / adaptation: - State: P - Function: Adapt the installed repertoire to external provider, skill and plugin options through a parent choice. - Disturbance / variety regulated: New external package versions and compatible catalogued plugins can change available runtime services. - Decisive decision or feedback right: Choose what to adopt, keep pinned, update or remove, then activate the resulting runtime composition. - Decision owner: The operator through the supplied plugin surface. - Supporting / enforcement mechanisms: External catalog refresh, option list, package-status/commit comparison, sync and reload. - Closure path: Operator selects a catalog entry or eligible update, packages are installed or locked to selected revisions, and reload starts or replaces capabilities for later work. - Boundary reachability: The installed panel fetches and represents external choices and invokes the native package and reload services. - Why this is / is not agent-owned: The runtime surfaces options and applies a human acceptance decision. It does not own prospective adoption judgment. - Evidence: catalogue and installed options, operator selection and sync, catalog adoption and reload, install and reload implementation - Basis: Pinned user-selected external-to-runtime adaptation path. - Confidence: High for package mode. - Caveats: Provider picker and generic agent authoring were not needed for this mapping. - External distinction: Configured external plugin catalogues and Git revisions, compared against installed and locked state. - Future / prospective distinction: Consider reusable services and extensions for later sessions or requests. - Adaptation option generated: The application presents available catalog entries and eligible package versions subject to constraints and pins. - Path back into current capability / S3: The accepted selection is persisted and synced; supported reload activates installed services for subsequent work.\">P</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No complete ultimate runtime identity-policy decision loop established. - Disturbance / variety regulated: Project resources can request consequential trust or permission scope changes. - Decisive decision or feedback right: No supplied path that adjudicates an ultimate organizational policy issue and thereby closes subsequent governance. - Decision owner: The operator owns workspace trust and permission configuration. Maintainers control distribution separately. - Supporting / enforcement mechanisms: Trust overlay, persistent directory decision, permission policy and optional pre-action review. - Closure path: Trust selects whether project resources load under an existing policy. No additional ultimate-policy resolution was reconstructed. - Why this is / is not agent-owned: Permission and resource admission alter the operating boundary without evidence of a distinct identity-policy closure process. - Evidence: project trust controls, saved command rules, workspace preset, proposed-action reviewer - Basis: Bounded absence across trust, permissions and plugin control. - Confidence: Moderate. - Caveats: The finding does not deny the material effect of accepting project-specific system prompts or plugins.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/f35d1f8f88765786fcc3d608a0c357e35d51b86b/assessments/ma/mare.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit f35d1f8f88765786fcc3d608a0c357e35d51b86b\">f35d1f8 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"1\" data-assessment-at=\"2026-11-24T14:21:35Z\"><th scope=\"row\"><a href=\"https://github.com/parlant/harness\" target=\"_blank\" rel=\"noopener\">H</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-24\">2026-11-24</time></td><td class=\"review-ref\"><a href=\"https://github.com/parlant/harness/tree/a45a50835d9fc51712a3afe0a2f97e8970781a0e\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision a45a50835d9fc51712a3afe0a2f97e8970781a0e\">a45a508 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Execute coding sessions against workspace, using model-selected shell/filesystem tools and subsequent feedback. - Disturbance / variety regulated: Unknown repository state and task/tool failures. - Decisive decision or feedback right: Choose and revise tool actions and completion. - Decision owner: Real model-backed coding session. - Supporting / enforcement mechanisms: OTP coordinator, provider stream, tool workers, persistence and retry. - Closure path: Generation emits tool calls, committed results return to next model turn, model returns terminal response. - Boundary reachability: Default coding harness tools and ReqLLM generation are packaged with daemon; no client attachment required. - Why this is / is not agent-owned: Removing model leaves transport and state but no task-level discretionary choice. - Evidence: lib/h/harness/coding.ex, lib/h/session/server/generation.ex, lib/h/session/server/tools.ex, lib/h/provider/reqllm.ex - Basis: explicit -\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: - State: A - Function: Attenuate conflicting writes among coding sessions by selectable isolated workspaces or read-only child roles, backed by writer leases. - Disturbance / variety regulated: Parallel parent/child or sibling sessions competing for writes to the same canonical cwd. - Decisive decision or feedback right: Root model chooses child read-only role or distinct prepared worktree, then responds to returned child receipts/outcomes. - Decision owner: Root model owns isolation/role choice; deterministic lease manager enforces same-workspace exclusion. - Supporting / enforcement mechanisms: Subagent schema, child cwd and read-only restrictions, WorkspaceLease waiter/handoff, durable settlements. - Closure path: Children operate under selected workspace/tool constraints; mutating calls wait for lease, resume on grant; child results return to caller. - Boundary reachability: Default depth-gated subagent exposes cwd/readonly and bash to prepare worktrees; daemon dispatch and writer lease are shipped. - Why this is / is not agent-owned: Model chooses separation in response to actual work; deterministic manager serializes same-workspace writes, without owning discretionary choices. - Evidence: lib/h/tools/subagent.ex, lib/h/session/subagents.ex, lib/h/workspacelease.ex, lib/h/workspacelease.ex, lib/h/session/server/workspacewait.ex, docs/architecture/subagents.md - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S3 / regulation: - State: P - Function: Owner regulates current commitments across daemon sessions using catalog state and targeted stop/lease handoff. - Disturbance / variety regulated: Concurrent operating sessions, contested workspace and conflicting current priorities. - Decisive decision or feedback right: Choose which current commitment to stop or prioritize for workspace allocation. - Decision owner: Authenticated daemon owner at the daemon-wide recursion. - Supporting / enforcement mechanisms: Live catalog, stop-session commands, holder identification and lease-fenced cancellation/handoff. - Closure path: Owner selects stop holder; waiting session prioritised, holder cancellation commits, lease released and waiter resumes. - Boundary reachability: Owner web inbox plus session workspace-wait controls invoke first-party command path; no custom composition. - Why this is / is not agent-owned: Autonomous root can steer/abort its own children but no shipped model with daemon-wide operating authority/view; owner has all-session view and decides exception. Fixed queue/account policy is support, not agent ownership. - Evidence: clients/web/lib/hweb/live/inboxlive.ex, clients/web/lib/hweb/live/sessionlive.html.heex, lib/h/session/server/workspacewait.ex, lib/h/workspacelease.ex, lib/h/session/server/commands.ex, lib/h/session/subagents.ex - Basis: explicit/structural - Confidence: medium - Caveats: Only daemon-owner current control; a root subtree has narrower agent steering rights. No A or C mode for autonomous daemon-wide controller inferred from generic owner API.\">P</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3* / direct audit: - State: C - Function: Expose separate artifact review channel to challenge coding session output against raw worktree or pinned Git blobs, with source-bound findings returned to session. - Disturbance / variety regulated: Unreliable self-reported coding outcome or incorrect changes. - Decisive decision or feedback right: Choose independently which evidence to inspect and what corrective findings to return. - Decision owner: Owner reviewer or composed autonomous reviewer; shipped model audit decision actor not established. - Supporting / enforcement mechanisms: Review file and commit API, raw Git reads, revision-bound selection and comment submission. - Closure path: Owner reviewer reads actual changed files/commit and sends anchored ask/note to the target conversation; composed independent model reviewer can use review APIs and return findings. - Boundary reachability: First-party web review and daemon review APIs are available alongside ordinary session runtime. - Why this is / is not agent-owned: Producing coding model does not determine what raw bytes the separate reviewer inspects or what findings are submitted; autonomy needs reviewer composition. - Evidence: lib/h/daemon/review.ex, clients/web/lib/hweb/live/reviewlive.ex, lib/h/daemon.ex, docs/architecture.md - Basis: structural - Confidence: medium - Caveats: No mandatory independent reviewer, no proof of reviewer competence; review may be performed by owner or composed agent. Ordinary subagent delegation alone not credited.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No demonstrated prospective external adaptation loop at daemon boundary. - Disturbance / variety regulated: Future shifts in model/provider/environment capabilities. - Decisive decision or feedback right: No returned adaptation judgment from prospective external sensing. - Decision owner: None established. - Supporting / enforcement mechanisms: Curated model catalog, user provider config, external usage polls in optional MultiCodex, context compaction. - Closure path: Account observations select present eligible route; provider edits affect configuration but no first-party prospective option-generation loop. - Why this is / is not agent-owned: Quota polling is present resource regulation; user-entered catalog and model picker are configuration, not external-and-future intelligence. - Evidence: lib/h/provider/reqllm/catalog.ex, docs/providers.md, extensions/multicodex/README.md, docs/architecture.md - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No runtime ultimate-policy closure at daemon-wide boundary. - Disturbance / variety regulated: Potential disputes over daemon purpose/ultimate policy. - Decisive decision or feedback right: No first-party identity-level resolution right evidenced. - Decision owner: Owner configures accounts, instructions and provider settings, not established S5 path. - Supporting / enforcement mechanisms: Owner authentication, config, instructions and tool selection, extension settings. - Closure path: Config changes govern subsequent requests but no identity/policy matter routed to ultimate authority and returned as such. - Why this is / is not agent-owned: Owner controls local tool/config boundaries, but ordinary configuration and task steering are not ultimate policy arbitration. - Evidence: lib/h/harness/coding.ex, docs/providers.md, docs/extensions.md, docs/architecture.md - Basis: structural -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/591cf5404a731452a36d1b840ba1c5fbd5f23a54/assessments/h/h.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 591cf5404a731452a36d1b840ba1c5fbd5f23a54\">591cf54 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-11-24T13:57:26Z\"><th scope=\"row\"><a href=\"https://github.com/dmoka/mini-harness\" target=\"_blank\" rel=\"noopener\">mini-harness</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-24\">2026-11-24</time></td><td class=\"review-ref\"><a href=\"https://github.com/dmoka/mini-harness/tree/4563935c87c4e22514a6ee3842fc51fc34ebe2fb\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 4563935c87c4e22514a6ee3842fc51fc34ebe2fb\">4563935 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: produce requested repository investigation and changes. - Disturbance / variety regulated: uncertain repository content, tool errors and incomplete changes. - Decisive decision or feedback right: select and revise tool actions, decide task completion. - Decision owner: model-backed coding agent. - Supporting / enforcement mechanisms: Session, tools, permissions, hooks, transport and shell. - Closure path: results/errors and optional stop-hook rejection enter the next model turn; agent continues or reports completion. - Boundary reachability: main creates Session and calls runloop; both backends return model-selected actions to the same dispatcher. - Why this is / is not agent-owned: removing the model leaves execution machinery but no discretionary action selection or completion. - Evidence: loop, file tools, shell, entrypoint. - Basis: explicit. - Confidence: high. - Caveats: plan mode and restricted commands can require human approval; Stop retries are bounded. No performance claim.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: - State: A - Function: attenuate concurrent coding-cell interference through selectable isolated writable checkouts and joined branch outcomes. - Disturbance / variety regulated: concurrent editing children modifying overlapping files or Git working state. - Decisive decision or feedback right: calling model chooses whether each child gets its own worktree and receives the resulting branch report for subsequent handling. - Decision owner: parent coding agent, while children retain local task discretion. - Supporting / enforcement mechanisms: runsubagent worktree parameter, parallel executor, unique Git branch/worktree creation, child process cwd and join. - Closure path: chosen isolated checkout becomes the child&#39;s operational environment; separate writes avoid same-checkout overwrite; branch/report returns to the parent&#39;s next turn. The isolation loop itself does not require branch merge. - Boundary reachability: runsubagent is a default core tool; model directly chooses worktree=true; concurrent calls launch separate children with selected checkouts. - Why this is / is not agent-owned: the model chooses when to invoke isolation; runtime implements the choice rather than deciding which tasks need it. - Distinct S1 units: concurrent task-specific coding children with own loop, checkout and branch/report deliverable. - Inter-S1 disturbance: editing agents otherwise share a repository working copy and may interfere through concurrent writes. - Attenuating coordination relation: selectable per-child unique Git worktree separates writes while work continues. - Feedback into subsequent S1 behaviour: each child executes in its selected cwd; branch/report returns to next parent turn for further work without concurrent shared-file edits. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the choice explicitly changes concurrent editing cells&#39; environment to isolate writes. - Evidence: fork/join, subagent and worktree, default tools, tests. - Basis: structural. - Confidence: medium. - Caveats: isolation, not proven conflict-free merge or distributed locking. Git merge may require human permission; child commit failure is not fully checked. Context-only mode does not sandbox arbitrary shell commands.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no supplied whole-system current-control loop at the local multi-cell boundary. - Disturbance / variety regulated: potential competition for shared commitments/resources. - Decisive decision or feedback right: not established beyond task-local actions and delegation. - Decision owner: no evidenced S3 owner; human approves specific plans/commands, developer defines static permissions. - Supporting / enforcement mechanisms: tool lists, plan gate, permissions, fork/join and scope. - Closure path: no whole-system current-state intervention over resources/commitments. - Why this is / is not agent-owned: parent receives completed reports and selects subtasks, not whole-system resource bargaining or intervention over active cells; plan approval is task-local. - Evidence: session and join, plan, worktrees, permissions. - Basis: structural. - Confidence: medium. - Caveats: ordinary task management and integration do exist.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no supplied complementary audit loop distinct from ordinary investigation/verification. - Disturbance / variety regulated: potentially unreliable routine coding reports. - Decisive decision or feedback right: no specific independent audit judgment path. - Decision owner: no evidenced S3 owner. - Supporting / enforcement mechanisms: generic fresh-context subagent, file tools, configurable hooks and ordinary tests. - Closure path: subtask reports and configured hook failures return to ordinary task loop; no dedicated complementary challenge is wired. - Why this is / is not agent-owned: generic subagent prompt supplies arbitrary investigation, not complementary audit relation; generic hooks require external audit composition. - Evidence: subagent, fresh-context test, loop, hooks, stop test. - Basis: structural. - Confidence: medium. - Caveats: caller could request audit, or configure external verifier; not a shipped function-specific loop.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no material prospective external adaptation loop. - Disturbance / variety regulated: potential future changes in harness capability/environment. - Decisive decision or feedback right: no future-facing harness adaptation right established. - Decision owner: no evidenced S4 owner. - Supporting / enforcement mechanisms: memory, compaction, planning, model fallback and shell/tools. - Closure path: internal facts/summaries return into later prompts, not external prospective options into capability. - Why this is / is not agent-owned: memory cleanup merges internal notes; fallback and coding the user&#39;s target do not establish harness adaptation. - Evidence: prompt, memory, compaction, plan. - Basis: structural. - Confidence: high. - Caveats: no inference about maintainer roadmap or hypothetical self-editing.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no runtime ultimate-policy or identity-resolution path. - Disturbance / variety regulated: potential conflict over ultimate policy/identity. - Decisive decision or feedback right: no evidenced identity-level decision path. - Decision owner: static developer/user configuration and task-local human permission, not established S5. - Supporting / enforcement mechanisms: BASEPROMPT, AGENTS.md, settings.json, askhuman and plan gate. - Closure path: rules enter prompts and approval changes command/mode, not an ultimate-policy issue returned into operations. - Why this is / is not agent-owned: no concrete identity-level issue reaches an agent or legitimate parent through a shipped closure loop. - Evidence: base prompt, rules, human input, plan, settings. - Basis: structural. - Confidence: high. - Caveats: configuration ownership exists, but no S5 loop; maintainer governance outside recursion.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/38f28a502719ac3fb85de236bceded182a1fc7d3/assessments/dm/dmoka-mini-harness.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 38f28a502719ac3fb85de236bceded182a1fc7d3\">38f28a5 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"1\" data-assessment-at=\"2026-11-28T02:08:46+03:00\"><th scope=\"row\"><a href=\"https://github.com/isacssw/serra\" target=\"_blank\" rel=\"noopener\">Serra</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-28\">2026-11-28</time></td><td class=\"review-ref\"><a href=\"https://github.com/isacssw/serra/tree/fb356389548b8691685a552c527b4a3ef19091d5\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision fb356389548b8691685a552c527b4a3ef19091d5\">fb35638 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Carry out a project task and return a workspace artifact or supported response to the initiating job. - Disturbance / variety regulated: Changing chat requests, repository state, tool results and follow-up inputs. - Decisive decision or feedback right: Choose task actions within the brief and workspace, respond to feedback and produce work and a result. - Decision owner: The configured T3 or ACP model-backed Serra job worker. - Supporting / enforcement mechanisms: Audience-filtered brief, agent adapter, job-specific workspace, run tracking and reply delivery. - Closure path: Serra briefs and starts the model worker, follows the result, and can return follow-up information into the same job. The model&#39;s chosen actions produce the artifacts and reply. - Boundary reachability: Supported default/optional agent backends are deliberately integrated into the packaged job lifecycle. The owner supplies the backend and sign-in while Serra supplies the operational setup, dispatch and return. - Why this is / is not agent-owned: If the backend worker is removed, the first-party transport can still observe or relay but no one decides what work to carry out. Ownership belongs to the active worker as bound into the supplied Serra job. - Evidence: README.md, src/bot.ts, src/agent/acp.ts, src/bot.ts - Basis: Structural evidence from pinned first-party source. -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: Regulate direct write interference between jobs against the same repository. - Disturbance / variety regulated: Overlapping agent edits and checkout changes can interfere if independent jobs share a working tree. - Decisive decision or feedback right: Decide or revise job workspace isolation in response to concurrent work. - Decision owner: Serra supplies job-specific branch/worktree isolation. An autonomous coordination decision owner would require composition. - Supporting / enforcement mechanisms: Git worktrees and distinct per-job branches, with first-party creation or T3 workspace assembly. - Closure path: Each agent executes in the allocated branch/worktree, limiting collisions at the working-copy level. - Boundary reachability: The ordinary worktree job route passes workspace identity at launch. Serra makes ACP worktrees for the applicable mode and requests T3 worktrees through its backend. - Why this is / is not agent-owned: The allocation rule is predefined. The isolated workers own task actions, not arbitration of competing workspace commitments. - Distinct S1 units: Separate job-bound worker agents using the same underlying project repository. - Inter-S1 disturbance: Concurrent jobs could edit the same files and checkout state when run in a single project directory. - Attenuating coordination relation: One branch and working tree per job in the standard worktree-backed mode. - Feedback into subsequent S1 behaviour: The workspace boundary directs subsequent file actions to the isolated checkout. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: Distinct Git working directories specifically attenuate direct cross-job write interference. - Evidence: README.md, src/agent/worktree.ts, src/agent/acp.ts - Basis: Structural evidence from pinned first-party source. -\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S3 / regulation: - State: P - Function: Regulate currently active jobs after the owner restricts knowledge available to their audience. - Disturbance / variety regulated: An existing job may retain evidence whose allowed audience or approval changes while that job is active. - Decisive decision or feedback right: Decide to restrict or retire the in-force knowledge across affected jobs. - Decision owner: Local profile owner through the approved knowledge and audience controls. - Supporting / enforcement mechanisms: Current job list, audience checks against knowledge snapshots, held replies and rebriefing in a new worker. - Closure path: Owner retirement or narrowed scope changes the approved knowledge. The active-delivery gate can withhold affected replies and the next turn starts a worker with the revised brief and retained task branch. - Boundary reachability: The owner app exposes jobs and page controls, and the active daemon consults the resulting profile for its live current governance checks. - Why this is / is not agent-owned: The owner decides the shared information constraint. The daemon enforces the returned decision and no autonomous actor owns revocation. - Whole-system current view: The owner-facing Jobs state tracks running and blocked work across the profile. The runtime checks active job audience and which approval snapshot it received. - Current-control decision scope: Change in-force constraints on current worker evidence, affecting existing runs with formerly allowed knowledge. - Evidence: src/jobs.ts, app/main/ipc/proposals.ts, src/bot.ts, src/bot.ts, src/bot.ts - Basis: Structural evidence from pinned first-party source. - Confidence: medium - Caveats: The finding is limited to current knowledge constraints that trigger intervention. Routine card approvals or deterministic backend selection alone do not establish S3.\">P</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: Sample whether the knowledge used by jobs actually supports answers, and surface conflicting or stale rules to the profile owner. - Disturbance / variety regulated: Ordinary worker citation and completeness reports can overstate the value or current validity of a page. - Decisive decision or feedback right: Judge contradictory or unsupported guidance and propose corrective evidence from a separate review role. - Decision owner: The read-only model reviewer in the supported weekly flow, with owner authority over applying changes. - Supporting / enforcement mechanisms: Periodic scheduler, approved snapshot reader, journal of request/reply/page usage, controlled re-answer comparisons and proposal validation. - Closure path: The model receives historical material and page texts, writes a review or rewrite proposal, and the owner can accept actionable findings into the profile that governs later work. - Boundary reachability: The live daemon schedules the first-party weekly review and supplies a configured read-only model run. - Why this is / is not agent-owned: The reviewer makes fresh, task-independent judgments over evidence. Owner approval governs the response to the findings. - Claim being audited: The pages cited and carried in real worker answers are current, useful and internally consistent. - Ordinary reporting path: Worker replies, knowledge use/citation and per-job status. - Complementary access path: Read the approved pages independently, inspect actual sampled requests/replies, and compare re-answers with and without a cited page. - Independence boundary: Separate review turns have their own supplied context and no need for a different provider. The evidence is bounded to the stored samples and pages. - Who acts on findings: The owner sees the digest and may accept corrective knowledge proposals or retire pages. - Evidence: src/daemon.ts, src/knowledge-review.ts, src/knowledge-review.ts, src/knowledge-review.ts, app/main/ipc/proposals.ts - Basis: Structural evidence from pinned first-party source. - Confidence: medium - Caveats: This audit concerns the knowledge-to-reply function. A PR review request is a separate external handoff.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S4 / adaptation: - State: P - Function: Adapt the profile&#39;s future job knowledge to changes in external project and user practices. - Disturbance / variety regulated: New human decisions, changed project context and repeated unanswered questions can make the current knowledge obsolete. - Decisive decision or feedback right: Decide which new or revised facts and procedures become approved future capability. - Decision owner: The profile owner reviewing proposed additions, rewrites, merges and retirements. - Supporting / enforcement mechanisms: Interview, weekly knowledge review, provenance, approval UI and audience-filtered brief assembly. - Closure path: New evidence is turned into a concrete proposal. Owner accept/merge decides its applicability, and subsequent worker briefs consume the approved copy. - Boundary reachability: The supplied app and daemon implement proposal construction, human acceptance and reads from approved knowledge. - Why this is / is not agent-owned: Model workflows produce candidate changes. The owner controls whether they enter subsequent operation. - External distinction: New owner information, changing working practices and project evidence surfaced by actual chat or review. - Future / prospective distinction: Determine what later jobs need to know across requests. - Adaptation option generated: New or revised knowledge page, with scope and recorded decision source. - Path back into current capability / S3: Promoted or merged pages feed the approved snapshot and hence subsequent job briefs. - Evidence: README.md, templates/interview.md, src/knowledge-review.ts, app/main/ipc/proposals.ts, src/brief.ts - Basis: Structural evidence from pinned first-party source. -\">P</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S5 / identity: - State: P - Function: Define the installed engineering assistant&#39;s persistent operating mandate and authority limits. - Disturbance / variety regulated: Different people and requests can conflict about who may decide, what the assistant represents, and off-limits work. - Decisive decision or feedback right: Set what the bot may do independently, who has permission to authorize work and which subjects are outside its mandate. - Decision owner: Legitimate local profile owner. - Supporting / enforcement mechanisms: First-party mandate interview, owner preview and apply, persistent policy and repeat brief assembly. - Closure path: The interview explicitly returns unresolved policy matters for owner decision. The owner can save or apply reviewed policy wording, and workers read it in later jobs. - Boundary reachability: The app exposes the interview and the policy service, and the default brief supplies the active policy reference to each worker. - Why this is / is not agent-owned: The model elicits matters and proposes wording. Only the owner can set the enduring mandate and grant a wider permission where allowed. - Identity / ultimate-policy issue: Which tasks the assistant is authorized to take, what it may disclose or promise, and who may widen its permission. - Ultimate authority in each claimed mode: The owner who defines and operates the profile. The interview cannot widen its own brief. - Return-to-operation path: Owner decides and saves or applies policy. The supplied brief makes that policy operative for later jobs, with widening reserved to explicit owner authority. - Evidence: templates/interview.md, templates/interview.md, templates/brief.md, src/brief.ts, src/brief.ts, app/main/ipc/brief.ts - Basis: Structural evidence from pinned first-party source. - Confidence: medium - Caveats: The finding is limited to the mandate and enduring authority limits. Ordinary workflow preferences are not treated as S5.\">P</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/40d4974d709204f75329ed980e3e1c0048daa449/assessments/se/serra.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 40d4974d709204f75329ed980e3e1c0048daa449\">40d4974 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-11-18T18:11:19+03:00\"><th scope=\"row\"><a href=\"https://github.com/pmndre/pine\" target=\"_blank\" rel=\"noopener\">PINE</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-18\">2026-11-18</time></td><td class=\"review-ref\"><a href=\"https://github.com/pmndre/pine/tree/c9dbfd129a8574459e37cfa834662b0fa8ca8a1b\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision c9dbfd129a8574459e37cfa834662b0fa8ca8a1b\">c9dbfd1 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Carry out event-triggered and requested tasks using model-directed tools and independent agent sessions. - Disturbance / variety regulated: Distinct user objectives, changing external events, file state, model responses and tool results. - Decisive decision or feedback right: Select tools, edits, responses and further tasks from current context. - Decision owner: Installed model-backed agent session, within owner-set access and model constraints. - Supporting / enforcement mechanisms: Task persistence, pi session runtime, source subscriptions, task queue, sandbox and tool gates. - Closure path: Model/tool feedback changes the next action; resulting files, emitted messages and task state persist into future interactions. - Boundary reachability: Standard pine init includes main agent and model session runtime; source events and operator prompts are both wired to the same task submit/execute path. - Why this is / is not agent-owned: The model makes task-level choices; PINE&#39;s deterministic event transport and permissions do not choose the task&#39;s substantive outcome. - Evidence: installed runtime, task submission and model dispatch, run and session loop, source-to-agent event path. - Basis: structural - Confidence: high - Caveats: Requires an actually configured reachable model. No live model task was executed during this source-based review.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: - State: A - Function: Attenuate concurrent operational agents&#39; conflicting edits to the same Git repository. - Disturbance / variety regulated: Simultaneous independent code edits can overwrite each other or conflict when brought back to the common branch. - Decisive decision or feedback right: Initiating agent selects isolated worktree mode for delegated/subagent tasks and then decides how to merge, retry or resolve conflicting branches after receiving results. - Decision owner: Initiating model-backed coding agent in a supported owner-trusted session; runtime only executes Git safety rules. - Supporting / enforcement mechanisms: Independent pine/ branches, worktree allocation, merge-tree checks, no-overwrite merge gates and conflict details returned to the initiating actor. - Closure path: Each child writes to a separate checkout; its returned branch information informs the initiator&#39;s subsequent integration. Merge conflicts identify overlapping files and require resolution before advancing the base. - Boundary reachability: delegate and subagent both expose worktree: true in the standard tools and return branch/merge instructions; the owner control API also offers conflict-aware merge operations. - Why this is / is not agent-owned: The lead can decide whether to isolate, how to integrate and how to revise an overlapping assignment; fixed Git commands merely implement/refuse that decision. - Distinct S1 units: Two agent/subagent tasks with separate model sessions, outputs and worktree branches, working on a shared project. - Inter-S1 disturbance: Concurrent writes to one checkout and divergent edits to the same file during integration. - Attenuating coordination relation: Runtime-enforced independent worktrees and explicit agent-selected merge/integration policy, with a conflict refusal rather than hidden overwrite. - Feedback into subsequent S1 behaviour: Branch return prompts the parent to merge or reassign work; rejected merge names overlapping files and blocks adoption until a revised child operation. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: The shipped worktree/merge subsystem explicitly addresses a concrete inter-worker write collision, including overlap detection and correction feedback. - Evidence: delegation worktree option and child return, parallel subagents, collision intent and isolation, merge conflict refusal, owner merge conflict return. - Basis: structural - Confidence: medium - Caveats: Isolation is optional and only source-proven; coordination of arbitrary separate non-code agents is not established. The base merge is not guaranteed to succeed; successful conflict resolution is actor-dependent.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S3 / regulation: - State: P - Function: Parent/operator current-control oversight of active agents and competing runtime capacity. - Disturbance / variety regulated: Multiple sessions and workers compete for execution slots and may continue a task that the owner no longer wants. - Decisive decision or feedback right: View installation-wide tasks, intervene with task cancellation, set agent execution mode and choose global concurrent-run capacity. - Decision owner: Authenticated installation owner through the bundled API/CLI/TUI. - Supporting / enforcement mechanisms: Global status and task listing, task cancellation, persisted model/mode limits and concurrency limiter. - Closure path: A canceled task stops/aborts subsequent execution; owner-selected per-agent mode affects later tool authorization; changed concurrency capacity governs scheduling after restart where documented. - Boundary reachability: The standard HTTP control API exposes /status, /tasks, /agents, /tasks/&lt;id&gt;/cancel, agent mode updates and global limits.maxConcurrentRuns configuration. - Why this is / is not agent-owned: The whole-installation intervention right belongs to the local owner, not the model or deterministic limiter; model-managed delegation is task-local. - Whole-system current view: The standard /status, /tasks and /agents endpoints expose work across agents rather than only one child&#39;s task status. - Current-control decision scope: Cancel a particular run, change an agent&#39;s operating mode, or choose available parallel execution slots. - Evidence: global listing, task stop and agent mode, cancellation endpoint, global concurrency parameter, runtime scheduling. - Basis: structural - Confidence: medium - Caveats: maxConcurrentRuns is a saved-next-start setting, not immediate preemption; no autonomous whole-installation S3 decision is credited. Simple human approvals for individual tool actions are not counted as S3.\">P</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: A sufficiently independent corrective audit of operational claims, beyond routine checks, was not established in the shipped installation. - Disturbance / variety regulated: A working agent may incorrectly report completion of a goal or of a delegated task. - Decisive decision or feedback right: The goal-mode judge issues MET/CONTINUE/BLOCKED from the agent&#39;s answer, not an independent review of changed files or external effects. - Decision owner: Goal status continuation belongs to judge/runtime; it does not own an independent evidence-based complementary audit. - Supporting / enforcement mechanisms: Goal judge prompt, runtime status, optional parallel tasks and owner review. - Closure path: A judge verdict can cause another goal round, but its information source is the producer&#39;s own report. No independent raw-evidence audit decision/return loop was identified. - Why this is / is not agent-owned: A second model call on the producer&#39;s answer is not an independent access path to operational reality; a user-created reviewer is not automatically present in the standard distribution. - Evidence: judge&#39;s exact input, judge and continuation, generic subagent, not an audit. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No shipped prospective environmental-intelligence-to-capability-adaptation loop was established for the PINE installation itself. - Disturbance / variety regulated: New external event types, model availability and future demands may motivate changing what agents can do. - Decisive decision or feedback right: Owners can ask the main agent to install sources, routes or agents; no first-party S4 decision loop was found that turns external future-relevant distinctions into options and subsequently changes current capability. - Decision owner: Owner controls explicit changes to topology and configuration; individual agents respond to subscribed events in their current jobs. - Supporting / enforcement mechanisms: General-purpose source subscriptions, model/manual lookups, routed events, agent creation and administrator tools. - Closure path: A source event can wake an agent and an owner-requested configuration change can affect later operations, but the inspected standard flow does not link those steps into a prospective adaptation judgment. - Why this is / is not agent-owned: Environmental reaction and ordinary runtime self-configuration are not by themselves a demonstrated future-oriented intelligence function. - Evidence: source subscription lifecycle, router event handling, agent construction needs owner request/approval, goal loop is owner-objective continuation. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S5 / identity: - State: P - Function: Set and revise installation-wide normative identity/behavior rules that govern all agents. - Disturbance / variety regulated: Divergent agent-specific behaviors and revised owner requirements for the whole installed organization. - Decisive decision or feedback right: Decide what collective rules, traits and behavioral obligations should hold for every installed agent. - Decision owner: The installation owner, acting as legitimate parent through explicit instructions or authenticated global-instruction control. - Supporting / enforcement mechanisms: Shared AGENTS.md read into every agent&#39;s prompt, exclusive main-agent edit tooling and authenticated owner shared-file API. - Closure path: Owner supplies an installation-wide policy decision; the main agent/owner writes the global rule file; subsequently agents read that file on their next message, changing their governed behavior. - Boundary reachability: The installed default main agent is explicitly charged with maintaining shared rules; all agents load shared instruction files and the owner API can edit them without creating a custom plugin. - Why this is / is not agent-owned: The main agent transcribes/implements owner-decided normative rules, but cannot legitimately substitute its own ultimate policy for the owner&#39;s. - Identity / ultimate-policy issue: Which binding behavioral rules and common agent identity/ethos should apply across all agent cells, not whether to approve a particular tool call. - Ultimate authority in each claimed mode: Authenticated owner only; no independent autonomous S5 closure claimed. - Return-to-operation path: Authenticated owner/main-agent shared-file update → saved global AGENTS.md → next-session prompt update for every agent → subsequent behavior under revised collective rules. - Evidence: global rules and owner write rights, global instruction incorporation, authenticated shared-file update, main agent&#39;s delegated role. - Basis: structural - Confidence: medium - Caveats: A simple per-tool permission is not S5. Credit is strictly to owner-decided collective normative policy changes; no automated S3–S4 strategic settlement or autonomous policy-maker is demonstrated.\">P</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/d6c36e01efe4a6adb1a4176eb2f7a18b57c56d0f/assessments/pi/pine.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit d6c36e01efe4a6adb1a4176eb2f7a18b57c56d0f\">d6c36e0 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"2\" data-assessment-at=\"2026-11-18T18:41:35+03:00\"><th scope=\"row\"><a href=\"https://github.com/yuzhiyang1/weora\" target=\"_blank\" rel=\"noopener\">Weora</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>2</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-18\">2026-11-18</time></td><td class=\"review-ref\"><a href=\"https://github.com/yuzhiyang1/weora/tree/b860b68d1aeff13d0b90394d3468bc9c60eff456\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision b860b68d1aeff13d0b90394d3468bc9c60eff456\">b860b68 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Perform substantive authorized agent changes and incident work under a persisted task mandate. - Disturbance / variety regulated: Changing user objectives, code/repository environment, model/tool results, tests and follow-up messages. - Decisive decision or feedback right: Configured worker agent chooses plan and authorized code/task actions through a native Pi session, and produces changed workspace/test/delivery evidence. - Decision owner: First-party configured Weora worker agent under shipped worker runtime; Pi model runtime is a separately installed adapter, not an independent credited organization. - Supporting / enforcement mechanisms: RunService, agent version/context, credential-authorized project sources, execution leases, sandbox tools, task/worker run events, continuation and code delivery. - Closure path: User task and approved scope to worker model turn, tool execution under grants to saved changes and reports, test/diff or delivery receipt to task and later follow-up. - Boundary reachability: Shipped backend code and APIs support this configured self-hosted mode with authorized owner, model runtime and workers. - Why this is / is not agent-owned: Without model-directed worker there is no substantive answer/edit decision; the deterministic scheduler merely reserves and invokes it. - Evidence: backend/src/weora/modules/runs/application/execution.py, backend/src/weora/modules/coordination/workerruntime.py, backend/src/weora/modules/delivery/application/service.py, README.md - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: Attenuate interference from simultaneous worker/task claims on shared objectives and incoming team instructions. - Disturbance / variety regulated: Independent workers or incoming threads may initiate duplicate effort, cross-owner task routing and overlapping work. - Decisive decision or feedback right: First-party coordination can select whether a request belongs to an existing task, stop/attach it instead of launching a competing new worker; actual inter-worker conflict adjudication needs an installed team configuration. - Decision owner: Composed main-session coordinator plus separately configured worker/task cells; source supports the decision, but concrete S1-vs-S1 interference scenario was not executed. - Supporting / enforcement mechanisms: Owner matching, single-task assignment, ticket mandates, canonical decision atomicity, source/author isolation, effect leases and worker dispatch. - Closure path: Overlapping work request → coordinator assesses existing ticket ownership and may attach/stop or accept one scoped task → decision persisted and worker gets the new input or no duplicate worker created. - Boundary reachability: Shipped backend code and APIs support this configured self-hosted mode with authorized owner, model runtime and workers. - Why this is / is not agent-owned: Not merely an at-least-once queue: main-session model has an explicit attach/accept/stop choice and an existing owner guard, although only constructor-grade conflict closure is evidenced. - Evidence: backend/src/weora/modules/coordination/engine.py, backend/src/weora/modules/coordination/mainsession.py, backend/src/weora/modules/coordination/workerdispatch.py - Basis: structural - Confidence: moderate - Caveats: Exact pinned-source/static code analysis, without external Pi/cloud credentials or live model execution. - Distinct S1 units: Separately assigned task/worker agents in one configured workspace. - Inter-S1 disturbance: Duplicate or overlapping incoming objectives can send two workers after the same work, or route new instructions to the wrong current worker. - Attenuating coordination relation: The model coordinator classifies accept/attach/stop and source identity; the state engine prevents fresh competing acceptance when an existing task owner holds it. - Feedback into subsequent S1 behaviour: Atomic decision either attaches new input to the existing ticket/worker, stops a ticket, or dispatches one new authorized worker with frozen scope. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: A constructible inter-worker duplicate-work/ownership attenuator is present, but not proven fully autonomous under a live cross-worker disturbance.\">C</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A(P) - Function: Regulate current workspace task commitments, pending worker attention, stop/retry/continuation and authorized work. - Disturbance / variety regulated: Pending or failed workers, changing human instructions, duplicate claims, unresolved attention and revoked access. - Decisive decision or feedback right: Main coordinator chooses accept/attach/stop/resume/requeue based on current workspace state, while authorized user/admin may pause scopes, stop work or decide approval boundaries. - Decision owner: Model-driven main-session coordinator in configured base mode; human workspace/task authority in parent mode. - Supporting / enforcement mechanisms: Main-session reads authorized state, current tickets/effects, assignment reports and notices; engine validates decisions and persists leases/status; UI/APIs expose task status and owner actions. - Closure path: Current ticket and worker reports → coordinator model decision → engine applies verified current task control → next worker assignment/input/resume or user hold; parent overrides access/stop/pause and the next worker honors it. - Boundary reachability: Shipped backend code and APIs support this configured self-hosted mode with authorized owner, model runtime and workers. - Why this is / is not agent-owned: A model makes actual disposition choices over whole scoped workload in main-session, while deterministic code checks leases and mandate. Parent choices are binding through exposed config/permission and run APIs. - Evidence: backend/src/weora/modules/coordination/mainsession.py, backend/src/weora/modules/coordination/engine.py, backend/src/weora/modules/coordination/service.py, backend/src/weora/modules/runs/application/service.py - Basis: structural - Confidence: moderate - Caveats: Exact pinned-source/static code analysis, without external Pi/cloud credentials or live model execution. - Whole-system current view: Scoped main coordinator reads authorized triggers, tickets, active worker assignments, unresolved human/peer inputs and effects within one project route. - Current-control decision scope: Accept/attach/stop/resume current objectives, choose when a worker may receive work, persist attention/wait and route completed/partial reports; human can revoke authorization/stop/pause work.\">A(P)</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3* / direct audit: - State: C - Function: Supplement worker claims with directly inspectable test outputs, code diffs and delivery receipts under a distinct human review. - Disturbance / variety regulated: Worker may assert successful task completion without current source/tests or authorization. - Decisive decision or feedback right: An authorized human can inspect recorded sandbox test output and branch diff independent of agent summary, then authorize or demand another run; full independent default audit actor is not bundled. - Decision owner: Constructed independent human/source reviewer, not the worker that generated the report. - Supporting / enforcement mechanisms: Sandbox test execution and code-host review artifacts, receipt APIs, run event stream and user follow-up/approval path. - Closure path: Worker report → independent source/test evidence view → user review or new directed task → follow-up run alters next task operation; source-level proof is configurable. - Boundary reachability: Shipped backend code and APIs support this configured self-hosted mode with authorized owner, model runtime and workers. - Why this is / is not agent-owned: The evidence originates from executed tests/source changes that can be checked outside the worker&#39;s self-report, rather than an LLM summary; independent audit is not default runtime autonomy. - Evidence: backend/src/weora/modules/delivery/application/service.py, backend/src/weora/modules/delivery/infrastructure/github.py, backend/src/weora/modules/runs/application/service.py, README.md - Basis: structural - Confidence: moderate - Caveats: Exact pinned-source/static code analysis, without external Pi/cloud credentials or live model execution. - Claim being audited: Worker claim of passing tests, completed change and valid delivery. - Ordinary reporting path: Worker status/report and task event feed. - Complementary access path: User can inspect actual saved test output and versioned code diffs/PR artifact through sandbox and code-hosting integration. - Independence boundary: Human source reviewer can use direct delivery/test evidence, distinct from model-authored report; first-party tools enforce source grants. - Who acts on findings: User approves, rejects or issues a specific follow-up requiring a new worker run.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-unknown\" title=\"S4 / adaptation: - State: ? - Function: Turn external future changes and review feedback into durable change of Weora agent capability. - Disturbance / variety regulated: Evolving model performance, new skills and external team requirements. - Decisive decision or feedback right: Human may select new agent version, skills and model configuration; a supported complete function-specific future-intelligence/option/return loop is not demonstrated. - Decision owner: Potential workspace owner through agent registry, not a verified autonomous S4 decision maker. - Supporting / enforcement mechanisms: Agent/version registry, skill sharing, model catalog and user settings; roadmap lists planned long-term memory/schedules. - Closure path: Capability/config changes can be saved and used on later runs, but external future signal → evaluated adaptation options → returned decision with tested future capability effect is unestablished. - Boundary reachability: Shipped backend code and APIs support this configured self-hosted mode with authorized owner, model runtime and workers. - Why this is / is not agent-owned: The repo ships configuration persistence but not a demonstrated prospective analysis loop; planned memory/RAG/schedules are explicitly excluded. - Evidence: backend/src/weora/modules/agents/application/service.py, backend/src/weora/modules/consolesettings/service.py, README.md - Basis: structural -\">?</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S5 / identity: - State: P - Function: Maintain legitimate workspace purpose and permitted agent identity, authorization and execution rights. - Disturbance / variety regulated: Unauthorized repository or Feishu inputs, version changes, unapproved writes, model credential abuse and scope expansion. - Decisive decision or feedback right: Human workspace owner sets agent versions, source grants, runtime/connection choices and approves scoped plans before worker tools can act. - Decision owner: Legitimate member/administrator at workspace recursion; model coordinators cannot invent or expand grants. - Supporting / enforcement mechanisms: Authorized context and access checks, agent registry versions, route grants, main coordination policy, worker mandate checks and tool gateway. - Closure path: Human policy/authorization → persisted workspace grants and agent/runtime version → repeated lease-time authorization checks → permitted or refused worker operation. - Boundary reachability: Shipped backend code and APIs support this configured self-hosted mode with authorized owner, model runtime and workers. - Why this is / is not agent-owned: Models can propose and route within approved scope, but cannot become the ultimate owner of access or task mandate. - Evidence: backend/src/weora/modules/coordination/service.py, backend/src/weora/modules/coordination/engine.py, backend/src/weora/modules/agents/application/service.py, backend/src/weora/modules/runs/application/execution.py - Basis: structural - Confidence: moderate - Caveats: Exact pinned-source/static code analysis, without external Pi/cloud credentials or live model execution. - Identity / ultimate-policy issue: Which agents, source permissions, repository actions, model resources and approved task scopes are legitimate for this workspace. - Ultimate authority in each claimed mode: Authorized human workspace/project owner; the coordinator and worker run under frozen mandates. - Return-to-operation path: Saved scope/config and version/grant settings are checked by the coordinator and each worker/continuation before tools execute.\">P</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/65cdcc079394ae5e3ab5f530ba935aef190de60a/assessments/we/weora.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 65cdcc079394ae5e3ab5f530ba935aef190de60a\">65cdcc0 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-11-11T17:41:35+03:00\"><th scope=\"row\"><a href=\"https://github.com/kuLm1Fs/lumak-ts\" target=\"_blank\" rel=\"noopener\">LumaK</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-11\">2026-11-11</time></td><td class=\"review-ref\"><a href=\"https://github.com/kuLm1Fs/lumak-ts/tree/ef1d2ddb16630e537c205fadb11031ba7bae6131\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision ef1d2ddb16630e537c205fadb11031ba7bae6131\">ef1d2dd &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Use workspace tools to answer a coding task and, when authorized, change code. - Disturbance / variety regulated: Ambiguous user goals, workspace state, tool errors, context pressure and permission decisions. - Decisive decision or feedback right: Select navigation, file/tool actions, delegation and revisions in response to observed results. - Decision owner: The active model-backed Agent owns the semantic tool and revision choices. Operator permission constrains certain actions. - Supporting / enforcement mechanisms: WorkspaceGuard, provider adapters, tool registry, dedup cache, role modes, session store and traces. - Closure path: Task → model request → selected workspace tool → result or denial enters messages → subsequent action or terminal answer. - Boundary reachability: CLI, embedded TUI and gateway instantiate Agent. Supported auto mode permits the loop to choose and apply local edits within the workspace. - Why this is / is not agent-owned: Choosing the next investigation or edit is model-owned. The runtime constrains and executes those choices. - Evidence: apps/cli/src/commands/chat.ts, packages/core/src/agent.ts, packages/core/src/runtime/loop.ts, packages/core/src/runtime/tool-call.ts, packages/core/src/providers/factory.ts - Basis: Pinned first-party source and declared distribution. - Confidence: High for the bounded structural finding. - Caveats: Source-static assessment. Provider behavior and real-world quality were not tested.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: No distinct response to lateral interference between independent coding units is established. - Disturbance / variety regulated: Concurrent children can share a workspace and issue overlapping operations. - Decisive decision or feedback right: Observe an actual cross-child conflict and coordinate a subsequent change in both affected operations. - Decision owner: Main model delegates tasks; the runtime executes child calls concurrently and joins results. - Supporting / enforcement mechanisms: Promise.all, parent permission ceiling, read-only roles and per-call tool execution. - Closure path: Children return outcomes to the parent. The shipped scheduling relation does not bind sibling conflict detection and adaptive redistribution. - Boundary reachability: Agent registry supplies the delegate tool. Child loops have no recursive delegate path. - Why this is / is not agent-owned: Delegation, capability limits and a final join support the parent task without defining a lateral conflict-resolution loop. - Evidence: packages/core/src/runtime/loop.ts, packages/core/src/runtime/delegate.ts, packages/core/src/runtime/permissions.ts - Basis: Pinned first-party source and declared distribution. - Confidence: High for the bounded structural finding. - Caveats: Source-static assessment. Provider behavior and real-world quality were not tested.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: No whole-system current-control mode is established across coding sessions. - Disturbance / variety regulated: Active session errors, tool requests, workspace selection and availability. - Decisive decision or feedback right: Intervene in whole-system resource commitments using a current operating view and returned decision. - Decision owner: Operator governs a local session and tools. The primary agent delegates its own work. - Supporting / enforcement mechanisms: Gateway conversation and trace views, approval prompts, loop limits and cancellation. - Closure path: Approvals or changed modes affect specific calls or sessions. - Boundary reachability: Gateway supports session and project state operations, while Agent handles each turn. - Why this is / is not agent-owned: Current workspace and per-call permissions do not form a portfolio-control decision or feedback relation. - Evidence: packages/gateway/src/server.ts, packages/gateway/src/state.ts, packages/gateway/src/chat.ts, packages/core/src/runtime/permissions.ts - Basis: Pinned first-party source and declared distribution. - Confidence: High for the bounded structural finding. - Caveats: Source-static assessment. Provider behavior and real-world quality were not tested.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: Complement the producing agent&#39;s own work report with a separate read-only inspection of code changes. - Disturbance / variety regulated: Latent implementation defects or gaps that remain after the producing agent&#39;s own tool feedback. - Decisive decision or feedback right: Inspect the target files and judge whether the implementation contains issues worth correction. - Decision owner: The separately instantiated reviewer model makes the review judgment. The parent model decides whether and how to revise. - Supporting / enforcement mechanisms: Built-in delegate tool, reviewer-specific prompt, role-bound read-only tools, shared workspace and returned DelegateReport. - Closure path: Primary model delegates review → fresh reviewer reads source files and reports → answer is appended as a tool result → parent model may edit or report in its next step. - Boundary reachability: Default Agent registry mounts delegate; auto permits invocation and approve can permit it. The reviewer prompt is shipped by the core prepack configuration. - Why this is / is not agent-owned: The child chooses its own read actions and findings in a fresh review context. The parent cannot substitute its own work report for that separate tool-backed review within this path. - Claim being audited: Whether selected existing code or recent edits fulfill the implementation intent without defects relevant to the delegated review. - Ordinary reporting path: The primary session observes its edit results, tool outcomes and its own response. - Complementary access path: The role-specific child can read and search the shared workspace directly, with a fresh prompt and without edit permissions. - Independence boundary: Separate child loop and prompt with read-only access. It uses the same configured provider and filesystem, and the parent chooses scope and contextual framing. - Who acts on findings: The primary model reads the returned reviewer answer and can adjust implementation or report findings. The harness does not mandate review or enforce a verdict. - Evidence: packages/core/src/agent.ts, packages/core/src/runtime/delegate.ts, packages/core/src/runtime/prompts.ts, packages/core/src/runtime/permissions.ts, packages/core/src/runtime/loop.ts, packages/core/package.json, prompts/subagent-reviewer.md - Basis: Pinned first-party source and declared distribution. - Confidence: High for reachability and separate artifact access; medium for practical independence under shared provider and parent-selected scope. - Caveats: Conditional on a reviewer call with suitable tools and a code artifact to inspect. Static source demonstrates the corrective return path, not measured effectiveness or mandatory remediation.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No prospective capability adaptation is established. - Disturbance / variety regulated: Workspace changes, context overflow and availability of existing skills or provider tools. - Decisive decision or feedback right: Observe future environmental change and select a durable adaptation returned to current capability. - Decision owner: The operator supplies skill files and provider configuration; the runtime selects available inputs for the current task. - Supporting / enforcement mechanisms: Skills selector, context truncation, optional MCP and persisted session memory. - Closure path: A matching skill or retrieved context alters the current prompt. - Boundary reachability: Built-in skill matching, session resume and provider selection are reachable. - Why this is / is not agent-owned: Selecting stored guidance and reacting to current input are local operational behaviors. - Evidence: packages/core/src/runtime/loop.ts, packages/core/src/skills/selector.ts, packages/core/src/skills/store.ts, packages/core/src/runtime/session.ts - Basis: Pinned first-party source and declared distribution. - Confidence: High for the bounded structural finding. - Caveats: Source-static assessment. Provider behavior and real-world quality were not tested.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No ultimate identity or policy arbitration is established. - Disturbance / variety regulated: Current tool permissions and configured role boundaries. - Decisive decision or feedback right: Arbitrate system mandate or ultimate policy and return a binding decision. - Decision owner: The operator sets the tool mode and workspace; developer-defined role rules enforce limits. - Supporting / enforcement mechanisms: CLI modes, approval gates and child permission ceiling. - Closure path: Per-action approval and policy selection change what may run in the current session. - Boundary reachability: Explicit CLI/Gateway approval and plan modes are shipped. - Why this is / is not agent-owned: User consent to an action and a constructor policy do not establish a first-party ultimate identity decision process. - Evidence: apps/cli/src/commands/chat.ts, packages/gateway/src/chat.ts, packages/core/src/runtime/permissions.ts, packages/core/src/runtime/delegate.ts - Basis: Pinned first-party source and declared distribution. - Confidence: High for the bounded structural finding. - Caveats: Source-static assessment. Provider behavior and real-world quality were not tested.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/b29fcd0709bdf141f7b15f579d4f05a57ad585ff/assessments/lu/lumak.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit b29fcd0709bdf141f7b15f579d4f05a57ad585ff\">b29fcd0 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-11-08T15:12:56+03:00\"><th scope=\"row\"><a href=\"https://github.com/chenofchina/onion-harness\" target=\"_blank\" rel=\"noopener\">Onion Harness</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-08\">2026-11-08</time></td><td class=\"review-ref\"><a href=\"https://github.com/chenofchina/onion-harness/tree/dc2be116eddad9c45018d0d8590fa6cc96387bfe\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision dc2be116eddad9c45018d0d8590fa6cc96387bfe\">dc2be11 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: first-party hosted model agents interpret user tasks and perform tool or deliberative work in local environments. - Disturbance / variety regulated: changing user goals, tool results, file/task conditions and differing model-seat arguments. - Decisive decision or feedback right: model-backed agent chooses next task-level action/tool call or substantive seat reply/rebuttal from prompt and feedback. - Decision owner: model-backed agent actor in normal mode; individual seat agents in Roundtable. The deterministic Onion application and external engine transport the choice. - Supporting / enforcement mechanisms: EngineLoop, provider adapters, executor registry, sandbox, Plan/Standard/Strict mode, approvals, memory, task events and configured ceilings. - Closure path: agent-selected call reaches an Onion executor, tool result returns to engine context for further agent choice; Roundtable seat replies enter the shared transcript and later rounds/final consensus. - Boundary reachability: OnionRuntime.runtask wires live tools/options into EngineLoop.run; the API constructs and starts Roundtable in a supported application path, rather than only in tests. - Why this is / is not agent-owned: model-dependent action and substantive reasoning disappear with the agent actor, while retaining Onion&#39;s deterministic mechanics; the latter do not independently choose the goal&#39;s actions. - Evidence: runtime loop, tool creation and feedback, Roundtable turn/feedback. - Basis: structural. - Confidence: high for shipped model-backed action/seat loops; no claim of successful paid-provider E2E execution in this review. - Caveats: the internal loongagent dependency is not separately assessed; local app uses its installed engine and a configured model rather than a first-party foundation model.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: - State: A - Function: Roundtable reduces blocking disagreements among independent model-seat contributions to produce a coherent joint deliberative outcome or a bounded explicit divergence. - Disturbance / variety regulated: incompatible seat stances and directed rebuttals can prevent the meeting from converging. - Decisive decision or feedback right: the model-backed host chooses the first seat per round after reading the evolving transcript and outstanding disagreement; each seat can revise/rebut from shared feedback. - Decision owner: host model agent for the discretionary next-speaker selection; other seat agents own their subsequent replies. Deterministic consensus/budget computation does not inherit that discretion. - Supporting / enforcement mechanisms: shared transcript, validated seat IDs, fixed tail speaking order, agreement/rejection parsing, round/call/token ceilings and human breaker. - Closure path: conflict appears as rejected stances/rebuttals; the host reads the transcript and selects the next first speaker, seats read preceding positions on later turns; consensus or the recorded divergences determines whether to stop, continue or involve the human. - Boundary reachability: the user-facing Roundtable API creates an actual RoundtableOrchestrator, while speakingorder makes a live host model call on its first-party normal execution path. - Why this is / is not agent-owned: removal of host deliberation leaves only deterministic rotation, not the dispute-aware speaker choice; mechanical ordering and consensus calculation remain supporting machinery. The host&#39;s returned focus field is not presently forwarded as a direct seat instruction, so the positive witness is bounded to first-speaker selection plus visible transcript/replies, not a stronger agenda-control claim. - Distinct S1 units: 2–6 model-backed seats with separate replies and optional rebuttal targets. - Inter-S1 disturbance: concrete disagreeing stances/rebuttals about the shared topic, which block consensus. - Attenuating coordination relation: host selection uses the transcript and prompts priority to whoever can address the open disagreement; subsequent seats see the accumulated positions. - Feedback into subsequent S1 behaviour: next round&#39;s host prompt and seat prompts include preceding contributions, and the consensus result stops/continues the meeting. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: a real conflict representation (rejections/targeted rebuttals) is tied to disagreement-aware host choice and a next-round response path; generic message passing alone is not the credited function. - Evidence: host and seat prompts, host choice, rebuttal and consensus path, verdict implementation, rebuttal/breaker tests. - Basis: structural. - Confidence: medium; source proves a dispute-specific feedback design, not observed convergence improvement under live provider conditions. - Caveats: this is S2 in supported Roundtable mode, not in an ordinary single-agent session. The host model&#39;s optional close and focus JSON fields are not the decisive mechanical closure of a round.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S3 / regulation: - State: P - Function: parent/operator supervision of the current Roundtable&#39;s resource composition and commitments across its model-seat cells. - Disturbance / variety regulated: debate stalls, insufficient specialist coverage, divergent statements or unsatisfactory current answer distribution across seats. - Decisive decision or feedback right: the human operator chooses the meeting roster/model constraints at creation and can add a new seat, address one or all seats, and return a new directive while the meeting is underway or after the breaker. - Decision owner: the local human/operator at the application/meeting parent boundary; model host selection alone does not establish agent-owned whole-system S3. - Supporting / enforcement mechanisms: meeting status/roster/minutes, API mediation, capped seat count, inbox, event persistence, model-cost and breaker display. - Closure path: a user-added seat joins the next meeting round; a targeted message enters that seat&#39;s inbox and is delivered at its next speaking turn; post-meeting human input reopens a bounded follow-up without silently clearing prior consensus. - Boundary reachability: the shipped Roundtable UI/API connects operator messages and seat addition to the same live orchestrator and its subsequent rounds. - Why this is / is not agent-owned: the model host cannot decide to create extra provider seats or authoritatively change the operator&#39;s live constraints; these are returned human current-control decisions. Generic cancel and destructive-command approval are not separately counted as whole-system S3. - Whole-system current view: Roundtable&#39;s member roster, statements, per-seat usage, divergences and minutes are available to the user across its current operational seats. - Current-control decision scope: parent choices over team composition, targeted priorities and intervention within the bounded meeting; not an inferred global allocator across independent Onion tasks. - Evidence: Roundtable UI contract, human messages/follow-up, live seat addition, inbox return. - Basis: structural. - Confidence: medium; the positive parent claim is bounded to the current Roundtable, not whole installation-wide budgeting. - Caveats: the operator can be human and does not need to be modeled as an AI agent; no autonomous S3 resource/commitment discretion is established merely from timeouts/host ordering.\">P</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: a separate audit would have to compare ordinary operational success/claims against independent underlying reality and return findings to current control. - Disturbance / variety regulated: false reported completion, unsound execution, unobserved side effects or unverifiable model claims. - Decisive decision or feedback right: not established as a distinct first-party complementary operational audit right in the reviewed modes. - Decision owner: none evidenced for such a distinct audit; the optional safety-review model judges proposed code before execution, and the user can approve a flagged request, but neither audits a claimed completed operational outcome through another access path. - Supporting / enforcement mechanisms: code-only safety filter, Plan mode refusal, user confirmation, diff view, tests and logs. - Closure path: no first-party complementary direct-reality audit finding is wired to corrective control as a separate function. Safety-review verdicts affect the ordinary executor&#39;s pre-execution gate only. - Why this is / is not agent-owned: an isolated reviewer model is not an S3 owner without a complementary audit of operating reality; authors explicitly call it a filter, not final authority. - Evidence: review-gate invocation, code-only review, README warning. - Basis: structural. - Confidence: medium-high within the shipped runtime/reviewer/GUI paths inspected. - Caveats: no universal claim about unexamined third-party plugins or a user&#39;s own independent verification procedure.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S4 / adaptation: - State: P - Function: parent-governed prospective adaptation of the agent&#39;s future available model/tool/skill capabilities in response to demands from the external user/work environment. - Disturbance / variety regulated: new tool/provider/skill needs beyond the currently enabled local repertoire. - Decisive decision or feedback right: the working agent can formulate a reasoned future-capability change proposal, but only the legitimate local human/operator decides whether it changes the installed repertoire. - Decision owner: human parent for adoption of the future capability; no automatic agent-owned S4 closure is claimed. - Supporting / enforcement mechanisms: MetaTools proposal API, dry-run ledger diff, capability validation and versioning, MCP tool materialization and hot reload. - Closure path: user-supplied/newly encountered capability need reaches the agent prompt; agent may propose a new executor/provider/skill/MCP tool; parent applies the proposal; the next runtime constructs its tools/prompt from the revised state or hot-loaded MCP registry. - Boundary reachability: meta tools are added to the normal agent&#39;s live tool registry and afterledgerchange updates the shipped runtime, including persisted tool availability; this is not merely a developer roadmap or test fixture. - Why this is / is not agent-owned: only the parent approval changes capability. Counterfactually removing the parent leaves proposals un-applied and does not close adaptation; this is not S4=A. - External distinction: changing user tasks and available model/tool services create a capability gap that can be expressed through the tool&#39;s mandatory reason and proposal content; no autonomous external scanning is claimed. - Future / prospective distinction: requested changes alter tools/providers/skills for subsequent actions or sessions, not merely the immediate task answer. - Adaptation option generated: agent-proposed registration of an MCP tool, model-provider preset, executor or skill. - Path back into current capability / S3: approved ledger state is re-read by OnionRuntime / refreshed MCP tools and becomes an available action for subsequent S1 execution. - Evidence: default operating prompt, meta tool proposals, human apply/reload. - Basis: structural for shipped proposal/return; inferred for the external-demand-to-adaptation interpretation. - Confidence: medium-low. This is a supported parent-closed capability adaptation mode, not evidence of autonomous environmental forecasting or systematic S4 strategy. - Caveats: a generic user-chosen plugin is not S4 by itself; this positive claim is limited to the model-originated, reasoned future capability proposal and actual parent return path. No source trace establishes recurring environmental surveillance or measured adaptation effectiveness.\">P</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S5 / identity: - State: P - Function: parent-governed ultimate change to the agent&#39;s core identity and operating rules, rather than an ordinary task/tool approval. - Disturbance / variety regulated: tension between the current core behavior/policy and a desired enduring operating identity for future sessions. - Decisive decision or feedback right: human operator authoritatively accepts/rejects a model- or user-originated update to the persistent core system-prompt segment. - Decision owner: legitimate local human operator of the self-hosted agent, not the proposing agent or deterministic ledger. - Supporting / enforcement mechanisms: onionupdatesystemprompt, ChangeLedger validation/diff/version history, API confirmation and ordered system-channel prompt assembly. - Closure path: core operating-rule proposal reaches confirmation UI; operator calls apply/reject; accepted segment is persisted; composesystemprompt and OnionRuntime.composesystemprompt inject it into future model calls. - Boundary reachability: normal agent tool registry contains the prompt-update meta tool, and user-facing API applies proposals to live state read on every later task. No adjacent maintainer CI or unshipped governance actor is needed. - Why this is / is not agent-owned: model can suggest but cannot activate its own enduring identity/policy change. No separate autonomous S5 ultimate-authority mode is established. - Identity / ultimate-policy issue: the core segment begins with You are Onion and durable operating rules; changing that segment changes the identity-level instructions inherited by future tasks, distinguishable from approval of a particular shell command. - Ultimate authority in each claimed mode: only human parent mode positively established; autonomous policy proposal is not decisive authority. - Return-to-operation path: ledger apply persists the approved segment; the runtime composes the system channel from that state on the next run. - Evidence: core identity and policy, prompt-change proposal, parent application, runtime system-channel return. - Basis: structural. - Confidence: medium-high for the shipped parent closure; the grade does not imply the default agent authors its own constitutional rules. - Caveats: a generic per-tool confirmation is not counted as S5. This applies only when the human-authorized change affects the durable identity/core policy segment.\">P</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/2d4f179b0c40a972a750d2e91fbef975709c36d2/assessments/on/onion-harness.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 2d4f179b0c40a972a750d2e91fbef975709c36d2\">2d4f179 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-11-11T17:52:22+03:00\"><th scope=\"row\"><a href=\"https://github.com/sakomws/slack-agent-runtime\" target=\"_blank\" rel=\"noopener\">Slack Agent Runtime</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-11\">2026-11-11</time></td><td class=\"review-ref\"><a href=\"https://github.com/sakomws/slack-agent-runtime/tree/16bb262715b7bacb64c7466cf106063c2fdf6c93\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 16bb262715b7bacb64c7466cf106063c2fdf6c93\">16bb262 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: carry out bounded conversation/MCP actions and coding tasks based on model-selected next actions. - Disturbance / variety regulated: unstructured requests, tool replies, changing code/tests and model errors within a bounded assigned job. - Decisive decision or feedback right: choose subsequent MCP tool or coding workspace operation after observing results, and choose when to finish. - Decision owner: the first-party agent/tool and coding-worker loops supplied with an external inference model; the user selects the objective and the service bounds permissions. - Supporting / enforcement mechanisms: step budget, tool schema, WorkspaceTools, approval broker, allowlists, isolated checkout and separated publication credentials. - Closure path: Slack request or dispatched coding task → inference decision → tool execution → result injected into model conversation → next action or final result/PR artifact. - Boundary reachability: default Slack MCP path and the shipped allowlisted coding-job entrypoint invoke real first-party loops; no custom developer agent implementation is required. - Why this is / is not agent-owned: tool choice and iterative repair are model-discretionary, while approval and final publish are enforced by non-model layers. - Evidence: MCP agent loop, coding worker, tools. - Basis: implemented structural flow; no live inference run. - Confidence: high for agent-loop ownership, not for actual task success. - Caveats: the GitHub publication step uses separate credentials, and a human is required for merge; neither is credited as agent decision.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no demonstrated first-party regulation of interference among distinct autonomous S1 coding units at this recursion. - Disturbance / variety regulated: potential concurrent jobs writing to overlapping branches or projects, but no evidenced S2-specific coordination loop. - Decisive decision or feedback right: absent for inter-S1 collision resolution; admins choose work requests, while quotas/locks execute fixed limits. - Decision owner: no autonomous S2-specific coordinator identified in shipped runtime. - Supporting / enforcement mechanisms: thread state, active task tracking, policy quotas, repository allowlisting, fixed GitHub Actions dispatch. - Closure path: no first-party conflict signal → discretionary coordination → altered subsequent S1 behavior chain evidenced; isolated task guards are not this chain. - Why this is / is not agent-owned: scheduling/rate limiting does not demonstrate mediation of an inter-agent conflict. - Evidence: policy, coding dispatch, spec limitations. - Basis: bounded no-path after checking shipped dispatch, policy and coordination surfaces. - Confidence: medium-high within deployed runtime boundary. - Caveats: upstream GitHub may serialize or reject changes, but that is not first-party discretionary inter-S1 coordination.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no whole-installation discretionary present-operational supervision demonstrated. - Disturbance / variety regulated: current job failures, quota saturation and review/dispatch state are exposed but not used in a first-party whole-system control loop. - Decisive decision or feedback right: no shipped actor chooses portfolio priorities, reallocates work or changes current operational commitments from a whole-system view. - Decision owner: human administrators issue independent commands; a programmatic S3 owner is not established by their local job actions. - Supporting / enforcement mechanisms: durable Actions job-status queries, per-thread state and quotas, policy and stream cancellation. - Closure path: individual code status/review status queries return observations to requesters; no demonstrated whole-system current-view → supervisory choice → altered work portfolio path. - Why this is / is not agent-owned: current status reporting and deterministic quota enforcement are not discretionary whole-system control. - Evidence: technical specification, thread coordinator, coding plugin. - Basis: bounded source-static absence. - Confidence: medium-high for ordinary shipped modes. - Caveats: external human operations could build supervision on top; not counted without a first-party return path.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: review the correctness, reliability and security of a proposed code change through a model judgment separate from the coding worker. - Disturbance / variety regulated: builder omissions and errors that pass self-report or initial local tests. - Decisive decision or feedback right: report structured findings and select a validated severity-derived REQUESTCHANGES or APPROVE recommendation. - Decision owner: separately dispatched PullRequestReviewer model workflow; publication safety checks can downgrade its verdict. - Supporting / enforcement mechanisms: source diff extraction, exact SHA, JSON validation, check status, GitHub review publication and human merge authority. - Claim being audited: the submitted PR satisfies correctness, security and reliability requirements; reviewer does not merely summarize coding worker&#39;s completion. - Ordinary reporting path: worker summary, test report and PR diff/CI status. - Complementary access path: reviewer receives actual PR diff plus title/body with separate inference instructions, producing findings by file/line independently of worker self-report. - Independence boundary: reviewer is a distinct invocation with its own role and bounded input; same underlying provider/model or stronger institutional independence is not established. - Who acts on findings: review workflow publishes a permitted GitHub review or comment; maintainers and authors correct the change, with required checks/merge authority retained externally. - Closure path: PR head/diff → independently invoked model reviewer → validated findings/severity → GitHub review/comment → author/maintainer action before merge. - Boundary reachability: the shipped review &lt;repo&gt;#&lt;PR&gt; Slack command dispatches the review workflow; it is an opt-in built-in mode, not automatically run for every coding job. - Why this is / is not agent-owned: the reviewer generates an evaluative model judgment; deterministic review-event selection and publishing restrictions only constrain it. - Evidence: reviewer code, review plugin, review workflow architecture. - Basis: implemented separate review mode, source-static. - Confidence: medium-high in structural complementarity; review efficacy and provider independence untested. - Caveats: no automatic closed builder-fix/re-review loop proven; closure relies on normal GitHub author/maintainer feedback, so the mode&#39;s end-to-end effectiveness remains unverified.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no first-party longer-horizon scanning/adaptation decision path for the runtime&#39;s future capabilities. - Disturbance / variety regulated: prospective changes in user needs, provider/service ecosystem and platform behavior are mentioned in documents but not regulated by an operating adaptation loop. - Decisive decision or feedback right: no installed agent chooses future runtime strategy/options against external signals and returns them into current capability. - Decision owner: maintainers can revise roadmap outside the assessed runtime; no shipped S4 actor. - Supporting / enforcement mechanisms: inference web search for user tasks, roadmap, issue-oriented coding worker and spec review. - Closure path: normal user-requested coding can change external repositories; it is S1 task delivery, not foresight about this runtime&#39;s identity/capability. - Why this is / is not agent-owned: web search and document review serve immediate requests, not a prospective environment-to-adaptation loop. - Evidence: roadmap, README, technical spec. - Basis: bounded no-path for shipped first-party modes. - Confidence: medium. - Caveats: operator-maintained roadmap is not attributed to a deployed agent or parent-governed runtime S4 without return-to-operation evidence.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no evidenced first-party ultimate mission/identity decision and return loop at the runtime recursion. - Disturbance / variety regulated: role/credential access boundaries are protected, but the system&#39;s purpose/ultimate policy is not decided by the installed runtime. - Decisive decision or feedback right: no first-party agent or explicit parent policy path authoritatively revises the runtime&#39;s ultimate mission and binds later operation. - Decision owner: humans manage configuration, whitelists, deployment and merge permissions as local operational governance, not a proved S5 identity-mode closure. - Supporting / enforcement mechanisms: admin IDs, repository allowlists, MCP approval, credentials, model choice and separated privileged publication stages. - Closure path: local policy configuration gates requests; it does not demonstrate an ultimate-policy decision circuit, nor make approval requests S5 by default. - Why this is / is not agent-owned: permission checks and human approvals enforce task scope without selecting a durable system identity. - Evidence: policy module, technical spec, approval broker. - Basis: bounded absence, not a judgment on the human maintainer organization&#39;s actual policy. - Confidence: medium; no runtime identity decision path identified. - Caveats: configuration policy can reflect human values; this alone does not prove the required ultimate-policy function.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/2c490e2b9da35239ab17f1fd10a4f48c686b3367/assessments/sl/slack-agent-runtime.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 2c490e2b9da35239ab17f1fd10a4f48c686b3367\">2c490e2 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-11-05T21:55:57+03:00\"><th scope=\"row\"><a href=\"https://github.com/bondie/agent-harness\" target=\"_blank\" rel=\"noopener\">Agent Harness (ticket team)</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-05\">2026-11-05</time></td><td class=\"review-ref\"><a href=\"https://github.com/bondie/agent-harness/tree/6c011629ecf3f0cb2cfd72084502e58a31ad3206\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 6c011629ecf3f0cb2cfd72084502e58a31ad3206\">6c01162 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Model-directed analysis, effort estimation and approved ticket-specific code changes in a target project. - Disturbance / variety regulated: Variable tracker requirements, codebase structure, acceptance criteria, failing tests, reference-ticket evidence and QA findings. - Decisive decision or feedback right: The analyst/estimator interpret ticket content and choose analysis/forecast; the implementer chooses substantive code edits and next local repair from test or review feedback within the approved task. - Decision owner: Instantiated Claude Code subagent models as operational actors, explicitly invoked by the installed ticket skill; human owns the scope gate, not code-level reasoning. - Supporting / enforcement mechanisms: Task-specific agent instructions, project-test post-edit hook, configurable precedent MCP, approval gate and tracker-write guard. - Closure path: Ticket → analyst/estimator choices → human-approved implementation → model-selected edits → repository/test observations → corrections → QA result and handover. - Boundary reachability: /agent-harness:ticket is the advertised installed entry point and explicitly names the subagents; the implementer definition grants Read/Write/Edit/Bash and receives the project test hook when configured. - Why this is / is not agent-owned: Remove the task-operating models and the prompt/hook package cannot interpret tickets or produce discretionary code changes; the host executes the tool choices but does not replace the task-local reasoning right. - Evidence: ticket skill, implementer, test feedback. - Basis: structural first-party installed workflow. - Confidence: High for defined agent decision roles; medium for live host behavior not independently exercised. - Caveats: Requires a configured external Claude Code runtime, tracker and target project; offline estimator experiments are not equivalent to live plugin decisions.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: No evidenced inter-operational-unit interference attenuation loop, distinct from sequential work handoff. - Disturbance / variety regulated: A ticket can produce analyst/estimator/implementer disagreement, but no peer S1 oscillation or simultaneous incompatible commitments are detected and damped by a separate coordinator. - Decisive decision or feedback right: The lead follows a prescribed sequence and human gate; it has no evidenced S2-specific adjustment right over independent peer operations. - Decision owner: Lead role for local routing and human for plan changes; no separately demonstrated S2 owner. - Supporting / enforcement mechanisms: Fixed role sequence, approval before implementation, bounded QA cycles and role write restrictions. - Closure path: Task outputs pass to the next role; no qualifying peer-conflict signal → coordinating choice → adjusted peer behavior loop is established. - Why this is / is not agent-owned: Delegating roles and handing a result forward is not by itself regulation of interaction-generated operational variety. - Evidence: installed skill steps. - Basis: bounded structural absence. - Confidence: Medium-high. - Caveats: Other multi-team integrations are outside this ticket-team boundary.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: No demonstrated discretionary whole-system present-control allocation or operational-portfolio commitment loop. - Disturbance / variety regulated: Wrong estimates, implementation failures, failed tests and review findings are local task matters, not a cross-unit resource/commitment picture. - Decisive decision or feedback right: Human approves scope and external writes; lead gates a prescribed ticket sequence. No agent legitimately revises whole-system operational allocations. - Decision owner: Human for plan and write approval, implementer for task-local edits, prescribed skill for sequencing. - Supporting / enforcement mechanisms: Human AskUserQuestion before implementation, two QA correction rounds, configurable test command, tracker MCP write guard. - Closure path: Gate → approved individual ticket → implementation/review/handover; no cross-unit performance consolidation and current-control reallocation return. - Why this is / is not agent-owned: The lead&#39;s management label and task handoffs do not establish S3 portfolio authority at this recursion. - Evidence: ticket skill, tracker guard. - Basis: bounded structural absence. - Confidence: Medium-high. - Caveats: The human manager of multiple unrelated tickets could implement an external S3 that this package does not define.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: Distinct independent read-only QA inspection of implementation assertions before human handover. - Disturbance / variety regulated: Implementer claims of task completion despite erroneous code, missed acceptance criteria, missing tests or regressions. - Decisive decision or feedback right: The reviewer chooses approve or changes requested and reports verified path:line defects plus checks and criterion status independently of the implementer&#39;s report. - Decision owner: Separate reviewer-qa Claude Code subagent; the lead receives its verdict and routes requested corrections to the implementer. - Supporting / enforcement mechanisms: Explicit review step, reviewer disallowedTools: Write, Edit, NotebookEdit, direct git diff/git status and code-context reading, independent test execution and up to two corrective rounds. - Closure path: Implementer reports completion → distinct reviewer checks working-tree artifacts and runs validation → issue-specific verdict → lead sends defects back to implementer → new implementation and re-review → human sees evidence/verdict. - Why this is / is not agent-owned: The reviewer&#39;s substantive assessment/verdict is agent judgment on direct source/test evidence; the skill-owned orchestration returns it to the lead and influences completion. This is separate from ordinary implementer self-tests or a deterministic linter. - Claim being audited: Completed changes meet the ticket analysis and every acceptance criterion without production defects. - Ordinary reporting path: Implementer summary of files, tests and criteria returned to the lead after edits. - Complementary access path: Reviewer independently reads the actual uncommitted diff, status and surrounding files and executes read-only tests/linters/static checks. - Independence boundary: Separate named model subagent without edit tools; cannot edit audited code or merely reuse implementer self-report. It remains subject to the same provider/host and its invocation depends on lead compliance with installed skill instructions. - Who acts on findings: Lead routes verified QA findings into an implementer rework round and withholds final handover until the bounded review process completes or escalates to the human. - Boundary reachability: The installed primary /ticket skill explicitly calls reviewer-qa after implementer and reruns it on change requests; the reviewer definition prescribes primary-artifact inspection, a verdict and line-level findings. - Evidence: independent reviewer, review and correction steps, implementer report path. - Basis: explicit + structural first-party audit path. - Confidence: High for wired separation and corrective instructions, medium for compliance in unobserved live sessions. - Caveats: Prompt-level reviewer separation, not a cryptographically isolated verifier or automatic no-bypass acceptance gate. Claims of tests passing do not replace actual project test command provisioning.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No autonomous prospective adaptation of the ticket-team&#39;s organizational capabilities. - Disturbance / variety regulated: Historical ticket variability and changing complexity are used for current-task forecasting, not future operating-model change. - Decisive decision or feedback right: Estimator forecasts current ticket hours from precedents; no owned decision to revise future team tools, policy, capacity or capability. - Decision owner: Estimator for this task&#39;s prediction, user/developer for future plugin design and installed configuration. - Supporting / enforcement mechanisms: Historical precedent MCP and estimate P25–P75, offline model-evaluation scripts, explicit approved approach. - Closure path: Past tickets → estimate for the current task → human plan decision; no environment futures → strategic adaptation decision → operating-organization feedback. - Why this is / is not agent-owned: Reference-class forecasting is anticipatory about this ticket&#39;s effort, but does not itself establish S4 future-environment/capability adaptation. - Evidence: estimation step, estimator role. - Basis: bounded structural absence. - Confidence: High. - Caveats: External team planning informed by ticket forecasts could be a separate S4 outside this plugin.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No evidenced first-party ultimate-purpose, organizational identity or constitutional arbitration loop. - Disturbance / variety regulated: Risky code changes, tracker writes, plan deviations and unapproved commits are governed at an operational authorization level. - Decisive decision or feedback right: Human may approve implementation and individual write actions; no actor resolves a dispute about the team&#39;s enduring ultimate policy or identity. - Decision owner: Human requester for plan and action consent, installed rules/hooks for routine constraints; no packaged S5 owner. - Supporting / enforcement mechanisms: Explicit AskUserQuestion plan gate, no commit/push without human consent, subagent tracker-write denial hook. - Closure path: Proposed action → approval or denial → execute/stop; no identity/purpose dispute → legitimate policy-authority judgment → enduring organizational policy revision. - Why this is / is not agent-owned: Read-only write restrictions and per-action consent protect execution boundaries, not an S5 policy identity feedback loop. - Evidence: human gates, tracker guard. - Basis: bounded structural absence. - Confidence: High. - Caveats: Host global instructions and organizational identity policies reside outside this plugin.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/1ec53be3a1853bb4d51e279e16f4b959fe32b354/assessments/ag/agent-harness-ticket-team.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 1ec53be3a1853bb4d51e279e16f4b959fe32b354\">1ec53be &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"2\" data-assessment-at=\"2026-11-05T22:18:42+03:00\"><th scope=\"row\"><a href=\"https://github.com/berkesecicii/free-multi-agent-ai-council\" target=\"_blank\" rel=\"noopener\">JARVIS AI Council</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>2</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-05\">2026-11-05</time></td><td class=\"review-ref\"><a href=\"https://github.com/berkesecicii/free-multi-agent-ai-council/tree/20a93de357da82c39255932da71dfb12aeea2f49\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 20a93de357da82c39255932da71dfb12aeea2f49\">20a93de &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: attached specialist agents independently execute coding, web-research, reading or review tasks and return task results and observations. - Disturbance / variety regulated: codebase state, provider tool results, user questions, web evidence and unexpected errors within each assigned specialist responsibility. - Decisive decision or feedback right: role model decides its research or code steps, tool requests and content after observing context/tool outputs; host controls access approval and routing. - Decision owner: selected model-backed specialist (VISION/Claude CLI, FRIDAY/Codex, EDITH/Gemini or other installed supported agent), not the deterministic Python routing rules. - Supporting / enforcement mechanisms: CLIs/adapters, project-command/patch/search, browser/desktop bridge, role-scoped chat context, saved task/output state and human permissions. - Closure path: user/JARVIS assigns task → first-party launcher reaches signed-in provider agent and approved tools → model consumes tool observations and delivers artifact/findings → host records output → later team stage or user consumes it. - Boundary reachability: providers are explicitly wired by first-party adapters and runtime launch; team runner selects their actual connector and creates a bounded child chat/task rather than only naming hypothetical specialists. - Why this is / is not agent-owned: provider-backed agents choose task-specific actions after observations, while local approval prompts and quotas do not themselves create agent discretion. - Evidence: shipped connectors and task semantics; task launch; live provider launching. - Basis: source-reachable supported model execution modes. - Confidence: medium-high for structure; external paid/subscription models not exercised. - Caveats: the first-party host cannot prove the quality of any third-party proprietary model&#39;s internal reasoning.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: first-party grouping and connector-busy guards attenuate incompatible overlapping work across specialist runs while returning completed producer context to a later specialist. - Disturbance / variety regulated: simultaneous role workers attempting the same constrained provider connector, or a dependent role acting before a producer output exists. - Decisive decision or feedback right: human/model step plans indicate dependencies or independent stages; host accepts at most two same-group jobs and refuses two concurrent uses of a connector; it defers dependent stages until the current group&#39;s work is collected. - Decision owner: static coordinator constructor and plan authors, not an agent capable of negotiating runtime contention or autonomously repairing a conflicted schedule. - Supporting / enforcement mechanisms: modeljobs provider-busy check, threading.Lock, same-connector rejection, parallel grouping, grouping barriers, bounded prior-stage packet, and failure/cancellation statuses. - Closure path: candidate parallel group is tested for connector conflict → only nonconflicting roles launch; the next group waits for current completion → collected result is returned as bounded context to subsequent role; if provider already busy, the team exits with explicit error instead of colliding. - Boundary reachability: teamrunner executes these checks directly before invoking first-party configured model adapters, and persists the workflow state visible to the user. - Why this is / is not agent-owned: interference attenuation is specific to distinct S1 agents sharing provider capacity and result dependencies; its selection policy is configured/deterministic, requiring further autonomous composition for S2=A. - Distinct S1 units: enabled EDITH research, VISION coding and FRIDAY review/development workers operating in the same team request. - Inter-S1 disturbance: overlapping role calls compete for shared provider capacity; a consumer role can act on an incomplete producer result. - Attenuating coordination relation: connector-distinct parallel group admission and completed-group barrier with packet return. - Feedback into subsequent S1 behaviour: conflict prevents launch and surfaces team error; completion unlocks subsequent stage and provides its result, so downstream work waits for producer evidence. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the witness is runtime prevention of a specific conflicting simultaneous provider use plus an explicit inter-role completion barrier, not the fact that prompts mention other agents. - Evidence: group building, connector checks and barrier; shared runtime job and quota guards. - Basis: first-party structural constructor path. - Confidence: medium. - Caveats: no agent-level merge conflict resolution or general distributed work scheduling is claimed; configured write permissions/isolated chats prevent some interactions without solving arbitrary semantic conflicts.\">C</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A(P) - Function: JARVIS assigns present team work to available specialists and constrains who executes next; in a separate supervised mode the human approves and starts a proposed multi-role plan. - Disturbance / variety regulated: mismatch between request and expertise, specialist availability/quota, excessive handoff depth and pending current workload. - Decisive decision or feedback right: in automatic chat mode the JARVIS model chooses to hand an actionable brief to another specialist, and host executes it within a two-handoff current chain; in explicit plan mode the operator decides whether the proposed role/effort/step commitments begin. - Decision owner: autonomous JARVIS coordinator model in the active auto-handoff configuration; legitimate Mac user/operator in the first-party reviewed-plan and direct-call configurations. - Supporting / enforcement mechanisms: role/connector availability and quota scans, model-authored HANDOFF parser, fithandoff corrections, hop/visited limits, team-plan and team-start, task/role progress and user-visible review card. - Closure path: base A: coordinator sees current request and available agents → selects next specialist/brief → host validates target, quota and hop bound → launches next model into the same team turn → completed work returns for coordinator synthesis. parent P: operator inspects the proposed team steps/roles → confirms start or selects agents directly → startteam executes selected commitments, returns results and gives operator stop/rework control. - Boundary reachability: auto handoff is a shipped default (autohandoff true), splithandoff and continuation call the actual model launch; the explicit reviewed plan path is offered by first-party team-plan/team-start actions and takes effect on real role runs. - Why this is / is not agent-owned: the agent can select the next current work commitment in the autonomous configured mode, while the operator has a genuinely distinct authorization path in the explicit-team mode. Deterministic caps merely bound both decisions. - Whole-system current view: the coordinator is briefed on callable team roles, their available connector/quota, the current shared chat and prior outputs; the human sees the complete team plan and current task/agent statuses in the app. - Current-control decision scope: current division of requested work among available team members, next assignment and effort, task-step commitment and interruption, not a company-wide financial/resource allocation claim.\">A(P)</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3* / direct audit: - State: C - Function: the shipped build→review team shape can provide a distinct model reviewer with a host-read snippet of actual changed files, separate from the implementer&#39;s prose report. - Disturbance / variety regulated: implementer reports success without grounding it in actual changed content or a second critique. - Decisive decision or feedback right: the plan or default FRIDAY review stage chooses the review function; a model may give a critique, but the host constructs the limited separate artifact-evidence packet, and no mandatory independent review acceptance gate is shipped. - Decision owner: constructed reviewer role with model critical judgment, invoked only in selected plans; human controls whether that optional stage is included and acted on. - Supporting / enforcement mechanisms: default FRIDAY review stage, separate child chat, previous-stage report packet and host ProjectBridge reads of approved changed-file excerpts. - Closure path: build specialist reports completion → host reads approved changed files from attached project and supplies excerpt alongside untrusted implementation report → distinct reviewer model critiques it → critique enters team results and final JARVIS presentation for the user / next current action. - Boundary reachability: startteam defines a real default FRIDAY reviewer after VISION; collect reads actual project paths and appends changed-file excerpts; the runner invokes the reviewer using its own connector, when enabled and configured. Not every dynamic or explicitly planned workflow elects review. - Why this is / is not agent-owned: the reviewer can judge content independently of the implementer&#39;s wording, but first-party code only constructs a bounded evidence packet and optional review; the reviewer does not automatically receive independent command execution in kind=review, so C is safer than a strong autonomous audit owner claim. - Claim being audited: code implementation and claimed changed-file result from the prior build stage. - Ordinary reporting path: model-authored stage output saved as a team task result, then passed to downstream roles. - Complementary access path: host ProjectBridge.path(...).readtext() for approved changed-file requests, packaged as Changed file excerpts to the next review stage. - Independence boundary: separate model agent with actual file excerpts not supplied by model prose; however excerpts are partial, only for recorded approved requests, and reviewer has no independent project tool rights in this review stage. - Who acts on findings: reviewer returns concrete failure/missing checks through team presentation to the user; no automatic veto or remediation is claimed. - Evidence: default review stage and excerpt construction; review role prompt; bounded project file access. - Basis: constructor-specific alternate evidence path; no guarantee of mandatory audit or outcome correctness. - Confidence: medium-low due optional stage and incomplete raw-artifact coverage. - Caveats: the default team plan omits unavailable roles and a model-generated plan may omit reviewer entirely; source snippets are the same worktree the implementer can change, not an isolated verifier workspace.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no first-party prospective environmental-sensing and capability-adaptation loop is closed at the installed team recursion. - Disturbance / variety regulated: future model/provider or external market changes are not transformed into a selected capability change by a shipped S4 decision process. - Decisive decision or feedback right: research specialist answers current tasks, while operator adjusts config; there is no routine future-option evaluation and adopted update path. - Decision owner: not supplied as a distinct adaptation authority. - Supporting / enforcement mechanisms: web search/research role, quotas, scheduled chat tasks, local role settings. - Closure path: task-local research may feed immediate work, but no exterior/future intelligence → alternative adaptation → approved capability revision loop is implemented. - Why this is / is not agent-owned: live web search and code building within a user brief are S1; a scheduled task or quota warning alone is not future-oriented organization adaptation. - Evidence: research and code routing; team planner; scheduler. - Basis: bounded structural negative. - Confidence: medium-high. - Caveats: human can ask a research→build sequence to improve the software, but that does not create a first-party enduring S4 procedure at this recursion.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no distinct ultimate-identity or policy-conflict decision transaction is closed through a legitimate internal parent authority and return path. - Disturbance / variety regulated: conflicting purpose/ultimate-policy demands are not represented as a governable S5 issue by the application. - Decisive decision or feedback right: user grants OS/project permissions and configures agents, but no built-in exceptional identity/policy adjudicator is invoked and returned. - Decision owner: external Mac user and OS entitlement authorities for ordinary permissions, not a first-party S5 loop. - Supporting / enforcement mechanisms: per-chat permission tiers, explicit risky-command approvals, prohibited app/action checks, selected role charters and user settings. - Closure path: user approves a requested tool action and it executes or is refused; that is local operation permission, not identity issue → final legitimate policy decision → governed future activity under a new policy resolution. - Why this is / is not agent-owned: hard safety rails and permission consent are fixed constraints for S1/S3 operation; they are not a viable organization&#39;s policy/identity decision right. - Evidence: README permission and safety rails; permission mode and work decision routing; project bridge. - Basis: bounded structural negative. - Confidence: medium-high. - Caveats: this denies a first-party closure path, not the existence of legitimate human or OS-level authority outside the assessed recursion.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/713e4282b33db357f31b0ce2894da2edac983ebd/assessments/ja/jarvis-ai-council.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 713e4282b33db357f31b0ce2894da2edac983ebd\">713e428 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-11-05T22:14:55+03:00\"><th scope=\"row\"><a href=\"https://github.com/Mohamed-jarboui/agent-runtime-harness\" target=\"_blank\" rel=\"noopener\">LoopSmith</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-05\">2026-11-05</time></td><td class=\"review-ref\"><a href=\"https://github.com/Mohamed-jarboui/agent-runtime-harness/tree/0c6c7b170bc553be38909800ceb5132e52299e52\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 0c6c7b170bc553be38909800ceb5132e52299e52\">0c6c7b1 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Context-sensitive, model-directed workspace analysis and report construction through tools, handoffs and feedback. - Disturbance / variety regulated: Different project files, user objectives, tool responses, untrusted search results, coding/report findings, and reviewer feedback. - Decisive decision or feedback right: Choose file-inspection/search operations, tool arguments, model-generated findings/draft, and subsequent work from prior observations in configured live provider mode. - Decision owner: Model actor selected by AgentRuntime for the installed analyst role; first-party runtime owns constraints and tool execution, not the substantive task choice. - Supporting / enforcement mechanisms: Typed tool registry, provider resolution, JSON/tool validation, session/SQLite state, bounded loop, memory, permissions, approval and safe workspace tools. - Closure path: Goal → model agent receives system/context/tools → chosen tool/delegation or answer → stored tool result/error → updated model context → further choice or terminal workflow result. - Boundary reachability: CLI registers analyst roles and workflows; documented --provider option chooses configured live Anthropic/OpenAI-compatible provider. Default mock mode is explicitly labelled deterministic and not counted as autonomous S1 by itself. - Why this is / is not agent-owned: Live LLM selects meaningful investigation and writing actions; disabling the model leaves only scripted mock output and deterministic graph/tool enforcement. - Evidence: agent runtime loop, analyst role tools, CLI provider option. - Basis: explicit + structural first-party live-provider mode. - Confidence: High for model/tool decision wiring; actual model behavior/quality not exercised. - Caveats: Live credentials/model endpoint required; offline demo and evaluation suite cannot be substituted for live S1 evidence.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: No specific operational-unit interference attenuation relation with its own feedback is established in the shipped workflows. - Disturbance / variety regulated: Specialist steps may depend on previous outputs; concurrent/conflicting independent S1 behavior and a correction loop for their interaction are not demonstrated. - Decisive decision or feedback right: Coordinator role can delegate research and hand off drafting, while graph engine follows author-defined routes; neither detects interaction-generated peer oscillation. - Decision owner: Model coordinator for task delegation; developer-authored graph/deterministic runtime for ordered transitions. - Supporting / enforcement mechanisms: Allow-listed agent.delegate and agent.handoff, bounded depth/count, workflow contexts and conditional transitions. - Closure path: Coordinator → specialist result → next step, or workflow state → fixed branch; no peer disturbance observation → S2-specific attenuation decision → revised peer commitments loop. - Why this is / is not agent-owned: Role routing, delegation and deterministic sequence are organizational plumbing, not proof of a distinct S2 regulatory function. - Evidence: meta-tools/handoffs, coordinator role, workflow. - Basis: bounded structural absence. - Confidence: Medium-high. - Caveats: A developer may compose multiple competing S1 teams with custom coordination, outside this reviewed installed mode.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: No distinct discretionary whole-system present-control authority over a portfolio of operational commitments is shown. - Disturbance / variety regulated: Excessive tool calls, unsafe writes, retries, failed rubric checks and pending approvals; these are bounded by limits/gates within one task workflow. - Decisive decision or feedback right: Developer authors workflow transitions and caps; reviewer judges the report as a specific QA result; human approves individual writes, but no owner revises multiple S1 resource/priority commitments from a current whole-system view. - Decision owner: Operator/developer for envelope, runtime for deterministic steps and human for write permission; no separate cross-operational S3 manager in standard mode. - Supporting / enforcement mechanisms: Persistent workflow checkpoints, maxSteps/maxVisits, permission engine, approval state and structured reviewer verdict route. - Closure path: Draft → verification/review → revise/publish or human gate; this is local artifact acceptance, not whole-operating-system resource/commitment balancing. - Why this is / is not agent-owned: LoopSmith may be a reusable control-plane foundation, but it does not package a whole-portfolio S3 actor in the reviewed workflows; generic graph transitions alone do not count. - Evidence: workflow graph, workflow engine, permission defaults. - Basis: bounded structural absence. - Confidence: Medium-high. - Caveats: Higher-level orchestration/portfolio policy may be built by a customer from provided interfaces; no shipped specific owner/closure is established here.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: Evidence-facing independent report review, distinct from the report writer and fixed structural validators, with corrective return. - Disturbance / variety regulated: Generated reports can omit findings, cite nonexistent file lines or inaccurately describe workspace evidence while passing basic formatting checks. - Decisive decision or feedback right: Dedicated reviewer agent returns approved/needschanges, identified issues and explicit checkedEvidence judgments after spot-checking cited source with read-only tool. - Decision owner: Separate reviewer model role in shipped analyst workflow; the graph engine routes its verdict and the executor addresses findings. - Supporting / enforcement mechanisms: Reviewer tools:[&#39;workspace.read&#39;], permissions:{write:&#39;deny&#39;}, model instruction to inspect cited file/line, typed ReviewSchema and deterministic pre-review verifyReport structure checks. - Closure path: Researcher findings → executor draft → deterministic structure/coverage check → distinct reviewer reads cited source and renders verdict → failed verdict routes to draft revision with reviewer feedback → re-review or human escalation on visit cap. - Claim being audited: Draft technical improvement report accurately and completely presents workspace findings with valid citations and safe content. - Ordinary reporting path: Researcher model findings and executor model draft placed in workflow state; writer&#39;s own output is the completion claim. - Complementary access path: Reviewer has separate workspace.read access to actual workspace files and a required cited-line spot check, with structured checkedEvidence results; deterministic verifier supplies additional independently computed format checks. - Independence boundary: Named reviewer model role distinct from executor and researcher, its permissions deny file writes and it can directly inspect original code. It shares configured provider infrastructure and is not an external independent auditor; structural independence is at role/readonly-tool boundary. - Who acts on findings: Conditional workflow routes non-approval back to executor draft, inserting prior reviewer feedback; after visit limit, it asks a human whether to publish despite unresolved issues. - Boundary reachability: apps/cli/src/bootstrap.ts registers analystAgents/analystWorkflows; workspace-analyst is advertised in the README and has the review/return path first-party installed. - Why this is / is not agent-owned: The reviewer makes a discretionary evidence-verification judgment separate from writer&#39;s normal self-report; the code rule alone is not credited as S3. - Evidence: reviewer role/permissions, review and revision closure, installed bootstrap. - Basis: structural explicit first-party review closure. - Confidence: High for shipped definitions; moderate for live-model behavior because standard demo is deterministic. - Caveats: A single spot check is bounded evidence, not exhaustive verification. Structural checks and external provider performance cannot replace actual independent model review.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No closed future-environment sensing and strategic adaptation loop changing the harness&#39;s future organizational capabilities. - Disturbance / variety regulated: Historical memory and observations are used to answer the current task; provider fallback handles present availability rather than long-term adaptation. - Decisive decision or feedback right: Developer/operator changes prompts, agents, workflows and provider config; model planner selects current investigation steps only. - Decision owner: Developer/operator for prospective capability changes, task agents for current workflow. - Supporting / enforcement mechanisms: Persistent memory, context compaction, configurable workflow templates, model/provider registry, evaluation CLI. - Closure path: Stored observations → current task context or test report; no external-future model → adaptation choice → capability-configuration feedback. - Why this is / is not agent-owned: Persistence, task planning and model fallback are not sufficient for future-facing organizational intelligence. - Evidence: context management, planner instructions, CLI evaluation. - Basis: bounded structural absence. - Confidence: High. - Caveats: External builders could use benchmarks and workflow reports to guide future strategy, but that is not a first-party installed feedback path.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No first-party ultimate-purpose or identity dispute arbitration beyond per-operation permission rules and human action consent. - Disturbance / variety regulated: Unsafe tool arguments, writes, external MCP calls, destructive execution and untrusted input. - Decisive decision or feedback right: Operator configures policies and human approves particular side effects; no packaged S5 actor decides durable system purpose or constitutional boundaries. - Decision owner: External operator/human for static permission config/individual approval, deterministic policy engine for enforcement. - Supporting / enforcement mechanisms: Allow/deny/require-approval categories, persistent approvals, workspace sandbox and secret redaction. - Closure path: Tool request → permission check or human approval → execute/deny/resume, not identity-level dispute → legitimate ultimate authority decision → enduring organizational mandate. - Why this is / is not agent-owned: Model cannot override tool policy, and approvals are narrow operational gates, not ultimate policy identity choices. - Evidence: permission engine, human approvals, README boundaries. - Basis: bounded structural absence. - Confidence: High. - Caveats: User&#39;s external organization may have its own S5 beyond this library.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/7eb41a76f082be5690ca12269cc1eec41aa5a528/assessments/lo/loopsmith.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 7eb41a76f082be5690ca12269cc1eec41aa5a528\">7eb41a7 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-11-05T21:00:30+03:00\"><th scope=\"row\"><a href=\"https://github.com/rubin-johnson/maestro\" target=\"_blank\" rel=\"noopener\">Maestro</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-05\">2026-11-05</time></td><td class=\"review-ref\"><a href=\"https://github.com/rubin-johnson/maestro/tree/0589ff3b2b0d25baabff196a1dd64c2147048b8e\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 0589ff3b2b0d25baabff196a1dd64c2147048b8e\">0589ff3 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Code-changing task agents implement specified work units and respond to source/tool feedback. - Disturbance / variety regulated: Requirements, repository state, build/test failures, model response and review-requested revisions. - Decisive decision or feedback right: Implementation CLI-backed model selects coding steps and edits; revision requests lead to a new model-driven implementation attempt. - Decision owner: Launched model-driven implementer for local coding decisions, installed into Maestro&#39;s first-party work-unit execution route. - Supporting / enforcement mechanisms: tmux isolation, explicit work-unit spec/DoD, task limits, SQLite persistence, CLI backends and escalation. - Closure path: User work unit→Maestro spawns implementer→model edits repo files→tests/review results→model revision or final accepted code. - Boundary reachability: execute CLI and orchestrator instantiate real tmux coding agents with configured backends, not just mock or planned actors. - Why this is / is not agent-owned: Model actor exercises task-level file-change choice; Maestro&#39;s fixed phase machine supplies gates, not coding autonomy. External vendor CLI internals are not separately credited. - Evidence: orchestrator, tmux manager, CLI. - Basis: Shipped runnable model-directed coding process with corrective feedback into implementation. - Confidence: Medium-high for first-party route; provider runtime effectiveness not independently replayed. - Caveats: Actual model steps run in separately installed CLI products; first-party evidence is their orchestration contract and returned status, not vendor-harness architecture.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: No separate agent-owned regulation of specifically observed contention between parallel S1 implementation units. - Disturbance / variety regulated: Dependency readiness, parallel-file collisions and worker resource contention can occur across work units. - Decisive decision or feedback right: DAG dependency checks and maxconcurrent=4 semaphore select ready waves, but are deterministic ordering, not balancing of detected competing goals. - Decision owner: Operator for work-unit DAG; Python scheduler for static ordering and concurrency gates. - Supporting / enforcement mechanisms: Dependency graph, parallel executor, work-unit status, file scope checks and tmux windows. - Closure path: Predeclared dependency→ready/blocked status; parallel work-unit results→output records, not peer contention evidence→autonomous S2 arbitration→returned adjustments. - Why this is / is not agent-owned: A queue, DAG and semaphore are supporting coordination machinery but no distinct real-time S2 balancing authority is installed. - Evidence: workflow executor, parallel executor. - Basis: Bounded absence despite distinct simultaneous work units. - Confidence: Medium-high. - Caveats: Operator can encode dependencies to avoid conflict; not a self-sensing inter-S1 balancing loop.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: No model/agent-owned discretionary whole-system management of current operating commitments and resources beyond the authored work-unit sequence. - Disturbance / variety regulated: Failed unit, bad test result, model timeout, context exhaustion and blocked dependencies. - Decisive decision or feedback right: Fixed phase gates and escalation ladder retry/fail/advance per unit; code selects ready waves. Model-assisted decomposition serves task shaping, not a portfolio manager with authority over organizational tradeoffs. - Decision owner: User defines work-unit specs/priority/dependencies; deterministic orchestrator follows configured rules. - Supporting / enforcement mechanisms: Validator gates, model-tier escalation, retry budget, SQLite status, DAG and GitOps. - Closure path: Unit failure→preset retry/tier escalation; DAG dependency blocking→recorded status. No autonomous whole-portfolio capacity/priority/commitment renegotiation. - Why this is / is not agent-owned: Enforceable resource and quality gates are not an independent S3 deciding strategic current tradeoffs; reviewers judge claims, they do not manage fleet priorities. - Evidence: phase and escalation machine, escalation rules, decomposition. - Basis: Bounded absence after testing source-backed execution governance against S3 discretion threshold. - Confidence: Medium-high. - Caveats: A future user/controller could wrap Maestro in a portfolio S3, but the standard execution mode owns only per-unit rule machinery.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: Bounded independent code/spec reality check of implementation claims with a returned review verdict and enforced rework. - Claim being audited: Implementer asserts its work unit meets the original spec and Definition of Done and presents changed files/output. - Ordinary reporting path: Implementer process completion text, status, staged changes and routine command/test output feed the orchestrator. - Complementary access path: Fresh cross-model reviewer agents receive the original spec/DoD and are asked to inspect actual code files and Git diff independently; deterministic validator directly executes source/test checks rather than trust self-report. - Independence boundary: Reviewer runs in a distinct tmux agent session and model type selected to avoid collision with implementer, but uses the same local repo and is orchestrated by Maestro; no external institution or externally verified truth guarantee. - Who acts on findings: Orchestrator parses NEEDSREVISION and validation failure, blocks commit and re-enters implementation or escalates model tier; positive evidence can advance to commit. - Disturbance / variety regulated: Hallucinated completion, incomplete DoD, out-of-scope file changes, security/code-quality defects and misleading model claims. - Decisive decision or feedback right: Reviewer may reject implementation with file:line evidence, while independent validator can fail executable checks; orchestrator enforces corrective loop. - Decision owner: Distinct reviewer model owns evidence-based audit judgment; deterministic validator owns command-based test gate; orchestrator routes returned finding. - Supporting / enforcement mechanisms: Fresh reviewer prompt, different agent type, direct source access, git diff, file-scope manifest, test execution, verdict parser and retry/escalation. - Closure path: Implementer completion claim→fresh independent reviewer reads code/spec (plus test execution/diff)→verdict→orchestrator rejects/requests revision or accepts/commits→new implementation attempt. - Boundary reachability: The shipped review phase spawns its own tmux reviewer, sends actual work-unit spec/diff/file-scope instructions and persists result; source tests cover review/revision behavior. - Why this is / is not agent-owned: The reviewer challenges original operational claims with a separately acquired direct file view, not just repackaged implementer prose. The static accept/deny state machine is an enforcement channel. - Evidence: review creation and non-colliding model selection, reviewer instruction, orchestrator revision path, validators. - Basis: Source-traced alternative direct-code reality access, distinct judgment owner and closed returned correction in normal work-unit mode. - Confidence: Medium-high for implemented bounded audit route. - Caveats: Reviewers can err, share upstream tool vulnerabilities or be manipulated by inputs; using a different model does not alone prove independence, and this is not certified external audit.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No autonomous future-environment sensing and strategic organizational change loop. - Disturbance / variety regulated: Changing model quality/prices, future source architecture, toolchain updates and novel task types. - Decisive decision or feedback right: Operators configure ladder/backend; predictive risk, preflight and dynamic decomposition serve a current task&#39;s execution, not future organizational strategy. - Decision owner: External developer/operator for long-horizon capability changes; per-unit implementer/reviewer for present work. - Supporting / enforcement mechanisms: Provider ladder, cost tier, prediction, knowledge-base roadmap and context-budget monitoring. - Closure path: Failure→current retry with a stronger model; offline future development remains manual. No external scanning→future options→policy/operational mandate adjustment. - Why this is / is not agent-owned: Changing model tier in response to immediate test failures is operational retry, not adaptive prospective environmental intelligence. - Evidence: model escalation, prediction, orchestrator. - Basis: Bounded absence review. - Confidence: High. - Caveats: User can ask Maestro to implement a future plan, which is task-level S1 rather than its organizational S4.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No legitimate ultimate identity-policy governing body or returned parent-assisted mandate. - Disturbance / variety regulated: Unsafe code changes, permission policy, task scope and model/provider credentials. - Decisive decision or feedback right: User authors work spec/DoD, mode, policies and credentials; validator/reviewer enforce work acceptance rather than determine organizational identity. - Decision owner: Operator/developer for legitimate policy; deterministic gates and reviewer for local task acceptance. - Supporting / enforcement mechanisms: Manifest scope, approval mode, preflight DoD quality, explicit backend configuration and commit gate. - Closure path: User spec/config→bounded operational checks; no identity-level conflict→legitimate charter deliberation→binding mandate into S3/S4. - Why this is / is not agent-owned: Security and acceptance criteria around a work unit do not constitute self-directed ultimate governance. - Evidence: preflight, review, config. - Basis: Bounded absence review. - Confidence: High. - Caveats: A human owner may be S5 of a deploying team, but not installed as an autonomous or parent-governed Maestro role.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/466587e24fbc9020d697440ea720db9274be8207/assessments/ru/rubin-johnson-maestro.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 466587e24fbc9020d697440ea720db9274be8207\">466587e &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"1\" data-assessment-at=\"2026-11-11T20:20:32+03:00\"><th scope=\"row\"><a href=\"https://github.com/DaDozlov/harness-agent\" target=\"_blank\" rel=\"noopener\">heaw</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-11\">2026-11-11</time></td><td class=\"review-ref\"><a href=\"https://github.com/DaDozlov/harness-agent/tree/dfff7b2bfbd6fb08cb754461124ac8dab2053622\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision dfff7b2bfbd6fb08cb754461124ac8dab2053622\">dfff7b2 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: transform project/user tasks into model-chosen code and tool actions and incorporate test/tool results into the next action. - Disturbance / variety regulated: variable user goals, repository state, edit/test failures, model context loss, tool denials and provider errors. - Decisive decision or feedback right: choose next tools, arguments and when to delegate, plan, repair or answer after returned observations. - Decision owner: configured model agent operating through the first-party core loop; first-party runtime implements concurrency, tool result delivery and constraints. - Supporting / enforcement mechanisms: provider adapter, tool registry, permissions, session JSONL store, hooks, context compaction, limits and terminal UI. - Closure path: heaw chat/run → Session/model loop → selected tool invocation → structured tool result and feedback → revised model call or final response. - Boundary reachability: shipped CLI loads a configured model and core engine, executes the loop and exposes file/shell/MCP tools; no external application is required to give the model task discretion. - Why this is / is not agent-owned: model selects semantic work, whereas deterministic rule checks, forced approval and turn caps only constrain its actions. - Evidence: core loop, session, README CLI. - Basis: shipped model/tool structural path; confidence: high. - Confidence: high. - Caveats: no live API-connected execution or output-quality claim from this static review.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: - State: A - Function: attenuate conflicting file writes among concurrently working autonomous subagents by partitioning their authorized change surfaces. - Disturbance / variety regulated: two model-driven delegated workers may edit the same files or shared integration points in incompatible orders and overwrite one another. - Distinct S1 units: independently model-backed delegate worker sessions with their own contexts, tools and task-result feedback, operating alongside the parent and other worker sessions. - Inter-S1 disturbance: concurrent delegates&#39; writes to a shared checkout can collide; first-party documentation explicitly requires each writing delegate to have its own files, with the parent retaining shared integration files. - Attenuating coordination relation: the model-owned parent specifies separate file-glob scopes and shared-file ownership in delegate arguments; runtime converts each scope into a stricter writable permission view. - Feedback into subsequent S1 behaviour: out-of-scope write attempts are denied as tool results to that child model; its final report is returned to the parent for integration and follow-on task choices. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: file scopes regulate the specifically documented inter-worker write interference, whereas delegation alone merely assigns a task; these scopes also change what workers may do later. - Decisive decision or feedback right: choose the non-overlapping file ownership breakdown and assign each writing agent&#39;s scope; on denied edits the agent must revise work or report the boundary. - Decision owner: main model agent selects task scopes and file partitions; deterministic PermissionPolicy.restricted and Slots enforce access and concurrency, not the semantic partition choice. - Supporting / enforcement mechanisms: per-subagent files globs, writable restricted view, shared approval policy, maxParallel slots, child execution result back to parent. - Closure path: model issues parallel delegate({files: ...}) calls → runtime runs child contexts in parallel with disjoint writable sets → out-of-scope writes get denied → worker adjusts and reports → parent integrates shared work. - Boundary reachability: delegateTool ships in the agent toolset and directly applies args.files to child PermissionRestriction before running actual child Session; the bundled plan skill tells the model to group only disjoint-file parallel steps. - Why this is / is not agent-owned: deciding partitions is an operational coordination choice made by the parent model, not a static hard-coded scheduler. A user can omit files, so this is an explicitly supported capable mode rather than universal collision safety. - Evidence: delegate tool contract and enforcement, planning skill file partition advice, permission restriction. - Basis: structural optional first-party parallel-delegate mode; confidence: medium. - Confidence: medium. - Caveats: files restriction covers file tools, not arbitrary side effects of permitted shell commands; independent automatically generated plans can still choose overlapping globs. This is a coordination capability, not a formal conflict-free guarantee.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no evidenced whole-system current portfolio/resource regulation beyond one agent task&#39;s execution budgets and parent-to-child task delegation. - Disturbance / variety regulated: time/token/cost exhaustion, concurrent workers and incomplete steps are bounded locally but not bargained across an organizational operating portfolio. - Decisive decision or feedback right: session budgets and limit-sharing are deterministic; user approves particular plans/tool calls; no whole-current manager negotiates multiple independent organizational commitments. - Decision owner: model chooses S1 task actions and S2 file splits; operator/developer sets limits, with no installed S3 authority evidenced. - Supporting / enforcement mechanisms: shareOf available budget, maxParallel, approval UI, PLAN.md and beforeStop hooks. - Closure path: limit or plan approval changes a run or task; no cross-operational whole-current allocation/revision is returned to a portfolio of S1 units. - Why this is / is not agent-owned: budget arithmetic and user approval of a single plan are neither an S3 control owner nor a whole-system decision right. - Evidence: subagent budget share, plan and approval, design non-goals. - Basis: bounded negative; confidence: medium-high. - Confidence: medium-high. - Caveats: embedding heaw within a separate organizational control plane may add S3 externally.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3* / direct audit: - State: C - Function: constructor for separate browser-backed verification of a coding agent&#39;s changed UI, with a verdict returned to the first-party completion gate. - Disturbance / variety regulated: a code agent may self-report that a page works while its rendered layout, forms, console or network behavior is broken. - Claim being audited: the coding agent&#39;s implicit/explicit claim that changed UI functionality is ready to complete. - Ordinary reporting path: code agent&#39;s own tool/test results and final answer, which need not observe the rendered UI or real form interactions. - Complementary access path: separate tester model session with read-only code tools and isolated Playwright MCP browser examines changed live pages, form behavior, browser console/network and screenshots. - Independence boundary: tester has a different model context and browser/user-level observable surface; its read-only role and browser restrictions limit editing of the code whose claims are checked. Independence is relative to coding agent reports, not an external governance auditor. - Who acts on findings: configured beforeStop hook interprets Verdict: fix first and returns continue: true with actual feedback to the coding agent; otherwise attaches the tester&#39;s findings as a note. - Decisive decision or feedback right: configured tester judges observed browser behavior; deterministic hook parses its verdict and causes the original agent to continue repairs or report verified findings. - Decision owner: independently invoked tester model decides the browser-backed judgment. Project user/model running /setup composes the specific included skill recipe into config, so a ready-made always-installed auditor is not asserted. - Supporting / enforcement mechanisms: bundled setup-harness skill and TESTERAGENT text, runAgent hook context, event reporting, file-change list and optional browser MCP server. - Closure path: setup generates tester and completion hook → agent modifies UI → hook detects changed UI files → independent tester uses browser and verdict → feedback continue: true sends coding agent back to repair, or note informs final report. - Boundary reachability: src/skills/built-in.ts contains the exact first-party tester template and hook code, and src/core/hooks.ts/src/core/loop.ts execute configured beforeStop and runAgent; setup is an operator-selected supported mode. - Why this is / is not agent-owned: separate tester&#39;s model owns judgment on complementary browser observations; deterministic hook routes its decision, and the coding agent cannot substitute its own assertion for the tester&#39;s browser verdict. - Evidence: bundled browser tester recipe and hook, hook invocation, design and runtime tester feedback. - Basis: specific first-party conditional audit constructor; confidence: medium. - Confidence: medium. - Caveats: operator must configure and run /setup, provide a browser/app start command and enable the generated hook. Generic eval trials, deterministic npm test, JSONL traces and a merely commented reviewer in heaw init are not credited. Browser testing is conditional on UI changes and its own execution limits.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no shipped externally and prospectively oriented adaptation-options process with S3 return established. - Disturbance / variety regulated: model/tool evolution and repeated coding failures can prompt developers to refine harness instructions, but those are not a demonstrated external-future sensing loop. - Decisive decision or feedback right: /retro asks the same agent to analyze past session failures and propose fixes, leaving human to choose; no dedicated prospective environmental options decision is packaged. - Decision owner: model may suggest local repairs, user changes configuration; neither is shown governing future external adaptation with S3 dialogue. - Supporting / enforcement mechanisms: sessionreport, built-in retro skill, model catalog and configuration reload. - Closure path: a user may choose to edit project instructions after retro; no first-party environment trend → future option → present S3 capability regulation is evidenced. - Why this is / is not agent-owned: retrospective self-analysis and local environment configuration are not by themselves S4. - Evidence: retro skill, retro command, design scope. - Basis: bounded negative; confidence: medium. - Confidence: medium. - Caveats: a concrete external S4 capability could be composed using the general library API but is not credited from possibility alone.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no ultimate identity/policy matter reaching legitimate authority and returning as a governing organizational identity decision is shipped. - Disturbance / variety regulated: unsafe tool calls, plan uncertainty and user trust preferences are routine work restrictions; not ultimate purpose conflicts. - Decisive decision or feedback right: human approves plan/tool calls, developer changes configuration; no dedicated policy identity dispute route to legitimate authority is shown. - Decision owner: host user/project developer configures permissions and model identity but is not engaged by a shipped S5 decision protocol. - Supporting / enforcement mechanisms: finishplan, approval broker, protected paths and config. - Closure path: approved plan enters build mode and rejected tool calls are blocked, not resolved as a new mission/policy for future operations. - Why this is / is not agent-owned: single-task approvals and fixed policy do not become S5 even with a human in the loop. - Evidence: planning approval, permission policy, design non-goals. - Basis: bounded negative; confidence: medium-high. - Confidence: medium-high. - Caveats: the project owner ultimately controls software, but the runtime has no shown identity-level governance return path.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/ae4602bc8e5cc59370569b0870998954fe663e71/assessments/he/heaw.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit ae4602bc8e5cc59370569b0870998954fe663e71\">ae4602b &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"1\" data-assessment-at=\"2026-11-13T22:33:16+03:00\"><th scope=\"row\"><a href=\"https://github.com/KKKKhazix/agent-autoloop\" target=\"_blank\" rel=\"noopener\">Agent Autoloop</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-13\">2026-11-13</time></td><td class=\"review-ref\"><a href=\"https://github.com/KKKKhazix/agent-autoloop/tree/55189165943bcdd39b113faceb97b8e1eeacabbd\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 55189165943bcdd39b113faceb97b8e1eeacabbd\">5518916 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Run goal-directed tasks in external authenticated CLI agent sessions bound by first-party rule and receipt protocol. - Disturbance / variety regulated: Scheduled work, source events, code/task novelty, tool feedback and paused human decisions. - Decisive decision or feedback right: Running CLI agent chooses task solution, next action and structured receipt including ask, later, notice and new follow-up events. - Decision owner: Configured Codex/Claude/ACP/DSH CLI agent executing in supported first-party worker adapter; kernel only dispatches. - Supporting / enforcement mechanisms: Rules, Node worker, plugins, event log, durable session references and human card channel. - Closure path: Rule-matched event → Worker adapter invokes model-backed agent → result/receipt becomes kernel fact → follow-up event/ask/resume returns changed work to agent or its output. - Boundary reachability: Shipped worker and built-in adapters invoke installed agent processes; README documents real Claude/Codex/ACP multiround runs. - Why this is / is not agent-owned: No model means deterministic scheduler and receipts cannot solve an open-ended task. - Evidence: worker/run.ts, worker/agents.ts, README.en.md, plugins/codex/agent.ts - Basis: structural and documented tested adapters -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: Subject-scoped suppression of competing concurrently executing agent jobs routed into the same lane. - Disturbance / variety regulated: Two asynchronous S1 workers may process duplicate events or mutate one subject concurrently. - Distinct S1 units: Independent worker invocations for queued runs, potentially multiple configured agents and rule groups. - Inter-S1 disturbance: A second run on the same (group,lane) could conflict with in-flight work; repeat event for queued subject could be redundant. - Attenuating coordination relation: Kernel enqueue consolidates queued same-rule/lane events; claimNext forbids claimed run with equal group and lane, respecting group/rule/agent capacity. - Feedback into subsequent S1 behaviour: A claimed/finished run changes subsequent claim eligibility, allowing deferred worker invocation after the earlier owner releases lane. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: Conflict witness is shared subject-lane exclusivity, not merely a global worker-count limit; the same-subject lock prevents concurrent S1 attempts. - Decisive decision or feedback right: First-party group/lane coordination construction and worker lifecycle return are real, but agent-owned discretion over coordination is not shipped. - Decision owner: Deterministic kernel owns enforcement and developer composes agent task policy/subject granularity, so C rather than A. - Supporting / enforcement mechanisms: Event-sourced facts, queued/claimed run state, rules group, lane and maxActive. - Closure path: Source subject → enqueue/claimNext → exclusive lane reservation → worker finish/retry record → next queued run becomes eligible. - Boundary reachability: Run rules and claimNext execute in shipped kernel/host for configured worker adapters; unlike merely exposing a generic queue, lane exclusivity is function-specific. - Why this is / is not agent-owned: Removing the CLI models leaves materially same fixed conflict-avoidance policy; no agent selects coordination policy. - Evidence: kernel/decide.ts, kernel/rules.ts, README.en.md - Basis: structural -\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S3 / regulation: - State: P - Function: Human supervision of current hub-wide processing commitments and operating constraints. - Disturbance / variety regulated: Failed or blocked rounds, pending human decisions, unavailable agents, excess work and unreliable active rules. - Whole-system current view: CLI status/runs/why supplies current agent/rule workloads, pending cards, failures, usage and durations. - Current-control decision scope: Owner pauses/resumes particular rule, may replay skipped event scope, changes agent/rule concurrency and answers/halts in-flight decisions. - Decisive decision or feedback right: Owner selects which present workloads run and at what rule-level capacity. - Decision owner: Legitimate local human owner of the hub config and CLI. - Supporting / enforcement mechanisms: Status CLI, versioned rules, pause facts, claimNext gates, app notifications and cards. - Closure path: Current status/pending work → parent pause/answer/rule update → kernel facts and dispatch gate → subsequent running/queued work changes. - Boundary reachability: Shipped status, pause/resume, config hot reload and card-answer commands connect to active Node hub. - Why this is / is not agent-owned: Configured CLI agents act inside their assigned tasks; no first-party model chooses hub-wide current operating constraints. - Evidence: README.en.md, kernel/decide.ts, host/runtime.ts, cli/explain.ts - Basis: structural -\">P</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: Conduct a separate model-judged review of PR changes before optional merge/delivery. - Disturbance / variety regulated: An authoring agent&#39;s report may conceal defects or unsafe changes. - Claim being audited: Changed PR code is sufficiently correct and safe for delivery under trusted main-branch policy. - Ordinary reporting path: Author PR description and status/CI. - Complementary access path: Review plugin captures actual read-only Git commit diff and review points from trusted main, not executing untrusted PR code. - Independence boundary: A dedicated ephemeral Codex/reviewer process reads isolated snapshot, with no checkout or code writes, separate from authoring CLI agent; review exemption is explicit policy. - Who acts on findings: Delivery flow returns findings to author for new commit/re-review or blocks merge until findings disposition is recorded; main gate governs merge. - Decisive decision or feedback right: Reviewer model produces structured findings on direct diff evidence and its result controls subsequent delivery. - Decision owner: Configured independent reviewer agent instantiated by first-party delivery plugin. - Supporting / enforcement mechanisms: Review ledger, signed head-specific status receipts, trusted review policy, scope/mode parser, full CI and delivery state machine. - Closure path: PR head → independent source snapshot and review → findings/ledger and GitHub status → remediate/refresh PR → review and merge gate. - Boundary reachability: Shipped delivery adapter and review.ts executes configured external CLI model in read-only isolated process when delivery rules are enabled. - Why this is / is not agent-owned: A deterministic diff filter does not author discretionary findings; separate model reviewer does. - Evidence: plugins/delivery/review.ts, plugins/delivery/review-policy.ts, plugins/delivery/delivery.ts, README.en.md - Basis: structural - Confidence: medium-high - Caveats: Optional delivery feature requires setup and can exempt reviewers under explicit policy. No live PR review replay in this assessment.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No first-party prospectively generated option for changing the hub&#39;s own future organizational capability. - Disturbance / variety regulated: Event feeds and history show changing environment but current tasks and future scheduled runs are not system adaptation. - External distinction: Incoming GitHub/webhook events, cron schedule and worker errors. - Future / prospective distinction: Scheduled later receipt addresses future task execution, not future organization design. - Adaptation option generated: No built-in adaptation hypothesis and capability-change decision traced. - Path back into current capability / S3: Operator can edit rules and plugins directly but not from a supported S4-specific prospective feedback loop. - Decisive decision or feedback right: Not present as S4. - Decision owner: None established. - Supporting / enforcement mechanisms: Rules hot reload, events and periodic schedules. - Closure path: Current task outputs may schedule more work; this is S1 continuation, not S4 capability adaptation. - Why this is / is not agent-owned: A schedule and self-emitted task events do not establish autonomous future-environment option selection. - Evidence: kernel/decide.ts, kernel/rules.ts, README.en.md - Basis: structural negative -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No first-party substantive identity/ultimate-policy decision-and-return path at the deployed hub recursion. - Disturbance / variety regulated: Who handles events, agent capabilities and sensitive action approval are configured and enforced as task/operating rules. - Identity / ultimate-policy issue: No described in-boundary mechanism for raising and deciding changes to the overarching system&#39;s charter and legitimate ultimate authority. - Ultimate authority in each claimed mode: Human local administrator owns rules.json and installed agent credentials, but mere config edits do not establish S5 parent governance. - Return-to-operation path: Changed dispatch rules are enforced by hot reload, but this is not an evidenced policy-level proposal → legitimate deciding parent → returned charter decision. - Decisive decision or feedback right: No separately constructed S5 right beyond external rule ownership. - Decision owner: No positive S5 mode established within reviewed first-party boundary. - Supporting / enforcement mechanisms: Rules validation, local config, actor authorization, event data isolation and human cards. - Closure path: No evidenced identity-level decision loop; settings changes simply alter execution behavior. - Why this is / is not agent-owned: CLI agent cannot redefine system purpose; operator changing a rule is not sufficient to infer an ultimate-policy governance arrangement. - Evidence: README.en.md, host/config.ts, kernel/rules.ts, protocol/rules.ts - Basis: structural negative -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/3896a2de54399beb137f9e9959bb2587ebf4fc4a/assessments/ag/agent-autoloop.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 3896a2de54399beb137f9e9959bb2587ebf4fc4a\">3896a2d &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-11-05T21:29:46+03:00\"><th scope=\"row\"><a href=\"https://github.com/BlackJaxDev/local-agent-broker\" target=\"_blank\" rel=\"noopener\">Local Agent Broker</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-05\">2026-11-05</time></td><td class=\"review-ref\"><a href=\"https://github.com/BlackJaxDev/local-agent-broker/tree/86b09380e3393126d6c540787a7576a61d21565b\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 86b09380e3393126d6c540787a7576a61d21565b\">86b0938 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Model-controlled workers transform bounded objectives into answers, tool-mediated effects, or code-change proposals. - Disturbance / variety regulated: Uncertain objectives, changing tool results, failed or denied calls, and code-edit details in authorized source files. - Decisive decision or feedback right: The provider model selects its response, tool calls and next steps within broker-enforced limits; swarm leaves choose concrete source replacements. - Decision owner: External API model invoked as the active autonomous actor through the first-party broker loop; in swarm mode the per-phase root/leaf models choose plan and edits. - Supporting / enforcement mechanisms: MCP transport, exact-model check, prompt construction, tool registry, immutable snapshots, budgets, provider retries, session policy and parallelism semaphores. - Closure path: Caller starts a run → model chooses answer/tool action → broker executes allowed tool → result returns on the next model turn → completed answer; in swarm mode leaf proposals return through review and caller-controlled apply. - Boundary reachability: startagentrun invokes AgentRunRegistry.Start and AgentOrchestrator.RunAsync; optional swarm routes through RunSwarmAsync/RunNodeAsync in shipped production code, not a test-only agent. - Why this is / is not agent-owned: The model decides task content/actions. Hard tool caps and file permissions only constrain or reject those decisions, rather than replacing their discretion. - Evidence: MCP tool implementation, agent turn/tool feedback, swarm leaves. - Basis: Structural first-party model-execution and feedback path. - Confidence: High for code wiring; medium for real provider execution because no billed run was repeated here. - Caveats: A standalone broker invocation still needs explicit provider credentials and client authorization; provider cognition is not itself first-party broker implementation.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: No established adaptive inter-S1 conflict/oscillation attenuation with returned behavioral adjustment in the shipped modes. - Disturbance / variety regulated: Parallel child agents can propose overlapping edits to a shared source file; separately queued workers can contend for concurrency capacity. - Decisive decision or feedback right: The caller fixes allowed paths and limits; deterministic merger rejects overlapping source edits rather than negotiating a revised peer coordination response. - Decision owner: Caller for path allocations/limits; root model for initial task decomposition; runtime for conflict validation and static semaphore enforcement. - Supporting / enforcement mechanisms: Per-child path assignment, immutable base hashes, overlap rejection, provider-slot and swarm-slot semaphores. - Closure path: Parallel child edits → conflict checker either combines non-overlapping patches or fails the proposal; no installed conflict-resolution decision goes back into a new coordinated child round. - Why this is / is not agent-owned: Distinct S1 leaves and a real possible edit collision are present, but a rejection gate and initial delegation are not an S2-specific feedback regulator changing subsequent inter-S1 behavior. - Evidence: plan constraints, overlap detection, parallel execution. - Basis: Bounded negative functional assessment despite a structurally identifiable disturbance. - Confidence: Medium-high. - Caveats: External callers could retry with changed scopes; such a coordination actor/loop is not installed in the broker itself.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: No autonomous whole-system current-control authority over a portfolio of active work and shared commitments beyond bounded delegation rules. - Disturbance / variety regulated: Provider failures, spending/turn/tool budgets, child-run admission, timeout and cancellation. - Decisive decision or feedback right: Caller fixes model, task, tool permissions and budgets; swarm root generates a one-time file-scoped task plan, while the runtime enforces ceilings and aborts on failure. - Decision owner: Caller/operator owns shared limits and resource policy; model&#39;s root plan owns current task decomposition, not ongoing organizational capacity or commitments. - Supporting / enforcement mechanisms: AgentRunRegistry, global concurrency, AgentRunBudget, per-phase token reservation, node admission caps, failure propagation and status registry. - Closure path: Preset limits → runtime admission/scheduling/termination; the shipped loop lacks a whole-run current-state appraisal feeding discretionary reallocation of operational commitments. - Why this is / is not agent-owned: Model task splitting is not evidenced whole-system current-resource bargaining or authoritative intervention; semaphores/budgets enforce caller choices. - Evidence: run registry, swarm plan, limits and failure propagation. - Basis: Bounded negative after testing root-orchestrator and runtime-manager paths. - Confidence: Medium-high. - Caveats: Host clients may provide higher-recursion fleet S3; their decisions are outside this broker&#39;s boundary.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: Bounded model-owned source-backed review of child agent code-change claims before approval or application. - Claim being audited: Each leaf&#39;s proposed replacement is a valid contribution to the parent objective and success criteria. - Ordinary reporting path: Leaf model emits JSON path, basesha256, oldtext and newtext; runner collects child artifacts. - Complementary access path: A fresh parent review API request receives the unchanged child artifacts and broker-captured immutable source snapshots and original objective, not only the leaf&#39;s completion assertion. The deterministic merger separately validates base hashes/overlap. - Independence boundary: The review runs as a distinct provider phase after leaves finish, without their continuation or permission to modify their artifacts; the child cannot mark its own edits approved. The same exact model/provider family may be used and all inputs are broker-supplied snapshots, so this is bounded internal complementary inspection, not cross-model or external institutional audit. - Who acts on findings: RunNodeAsync rejects the entire swarm when the parent model returns approved=false; only positive review returns proposals to the run registry for caller review or explicit Windows application. - Disturbance / variety regulated: Plausible but faulty code replacements, mismatch to objective and misleading leaf success claims. - Decisive decision or feedback right: Separate parent reviewer model decides approved and summary after examining source and unchanged proposed edits; deterministic orchestrator enforces that verdict. - Decision owner: Review-phase provider model makes the substantive accept/reject judgment; runner parser and fail path are supporting enforcement. - Supporting / enforcement mechanisms: Immutable source snapshot capture, isolated phase request with no tools, review-specific instructions, JSON parse, merge collision check and no-change-on-rejection guard. - Closure path: Leaf proposals → fresh model review with original source/artifacts → verdict → rejection terminates with no approved changes, or approval exposes the proposal for caller acceptance and possible readback-checked application. - Boundary reachability: Optional production swarm uses RunNodeAsync for every orchestrator node, creates a distinct CreatePhaseRequest with context-file snapshots for review, and RunSwarmAsync exposes only approved changes. - Why this is / is not agent-owned: The reviewer independently judges a source-backed child claim rather than trusting its self-report; the deterministic parser does not supply the substantive review decision. - Evidence: review request and input wiring, review verdict closure, provider snapshot input, rejection test. - Basis: Structural distinct audit-judgment call with source evidence and returned corrective veto. - Confidence: Medium: model decision and wiring established in source; actual provider-backed judgments not replayed. - Caveats: Same model/provider can produce correlated errors; review sees captured source and proposals, not independently sampled live post-apply code. This is not a general-purpose S3 of all broker runs.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No shipped external/future environmental sensing, option formation, and adopted adaptation loop for the broker itself. - Disturbance / variety regulated: Changing provider options, future model costs/capabilities, repository evolution and new threats. - Decisive decision or feedback right: Caller selects actual model/configuration; keyword-based route advisor can recommend a model for the current objective, not revise future organizational capability. - Decision owner: Human caller/developer for model/policy upgrades; deterministic AgentRouteAdvisor for present-task recommendation. - Supporting / enforcement mechanisms: Exact-model catalog, task keyword classifier, provider error/retry diagnostics and operator settings. - Closure path: Current objective → static model recommendation → caller choice for this run; no external sensing→prospective options→capability adoption path. - Why this is / is not agent-owned: Task difficulty routing and provider retries respond to current execution, not environmental foresight or adopted future change. - Evidence: route advisor, broker config, run/model validation. - Basis: Bounded negative after route/adaptation candidates were inspected. - Confidence: High. - Caveats: A user may delegate future-looking research to an individual worker; that is operational S1 output, not an established broker-level S4.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No ultimate identity/policy deliberation and legitimate return-to-runtime decision loop at this broker recursion. - Disturbance / variety regulated: Task authority, source-file permissions, credential exposure, destructive editor commands and uncontrolled billed model execution. - Decisive decision or feedback right: Caller and configuration supply boundaries; deterministic validators reject unauthorized requests. There is no shipped identity/charter question escalated to and resolved by an ultimate authority with a returned mandate. - Decision owner: External MCP caller/operator for task authorization and security policy; program validators enforce rather than govern its content. - Supporting / enforcement mechanisms: Explicit workspace/allowed paths, tool annotations and allowlist, destructive/mutation flags, exact model requirement, budget checks and secret-path denial. - Closure path: Operator-supplied scope → fixed request guards → permitted/denied run; no identity-level issue→legitimate parent authority→binding policy decision→changed subsequent operation. - Why this is / is not agent-owned: Ordinary permissions and operator review of a patch are run-level controls, not a first-party S5 organization or parent-governed identity loop. - Evidence: protocol policy, repository path policy, run admission. - Basis: Bounded negative for the standard-distribution authority path. - Confidence: High. - Caveats: The parent organization using the broker may have an S5; its external decisions are not part of this local harness&#39;s evidenced operating structure.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/a8b7d8aa1af85fabe5957742ed23c9358007621d/assessments/lo/local-agent-broker.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit a8b7d8aa1af85fabe5957742ed23c9358007621d\">a8b7d8a &#8599;</a></td></tr>"];
